INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,131,'As-Saaffaat','إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ','ہم نیک لوگوں کو ایسا ہی بدلہ دیتے ہیں','Indeed, this is how We reward the good-doers','हम यक़ीनन नेकी करने वालों को ऐसा ही बदला दिया करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,132,'As-Saaffaat','إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ','بےشک وہ ہمارے مومن بندوں میں سے تھے','He was truly one of Our faithful servants','बेशक वह हमारे (ख़ालिस) ईमानदार बन्दों में थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,133,'As-Saaffaat','وَإِنَّ لُوطࣰ ا لَّمِنَ ٱلۡمُرۡسَلِينَ','اور لوط بھی پیغمبروں میں سے تھے','And Lot was indeed one of the messengers','और इसमें भी शक नहीं कि लूत यक़ीनी पैग़म्बरों में से थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,134,'As-Saaffaat','إِذۡ نَجَّيۡنَٰهُ وَأَهۡلَهُۥٓ أَجۡمَعِينَ','جب ہم نے ان کو اور ان کے گھر والوں کو سب کو (عذاب سے) نجات دی','˹Remember˺ when We delivered him and all of his family','जब हमने उनको और उनके लड़के वालों सब को नजात दी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,135,'As-Saaffaat','إِلَّا عَجُوزࣰ ا فِي ٱلۡغَٰبِرِينَ','مگر ایک بڑھیا کہ پیچھے رہ جانے والوں میں تھی','except an old woman, who was one of the doomed','मगर एक (उनकी) बूढ़ी बीबी जो पीछे रह जाने वालों ही में थीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,136,'As-Saaffaat','ثُمَّ دَمَّرۡنَا ٱلۡأٓخَرِينَ','پھر ہم نے اوروں کو ہلاک کردیا','Then We ˹utterly˺ destroyed the rest','फिर हमने बाक़ी लोगों को तबाह व बर्बाद कर दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,137,'As-Saaffaat','وَإِنَّكُمۡ لَتَمُرُّونَ عَلَيۡهِم مُّصۡبِحِينَ','اور تم دن کو بھی ان (کی بستیوں) کے پاس سے گزرتے رہتے ہو','You ˹Meccans˺ certainly pass by their ruins day','और ऐ अहले मक्का तुम लोग भी उन पर से (कभी) सुबह को और (कभी) शाम को (आते जाते गुज़रते हो)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,138,'As-Saaffaat','وَبِٱلَّيۡلِۚ أَفَلَا تَعۡقِلُونَ','اور رات کو بھی۔ تو کیا تم عقل نہیں رکھتے','and night. Will you not then understand','तो क्या तुम (इतना भी) नहीं समझते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,139,'As-Saaffaat','وَإِنَّ يُونُسَ لَمِنَ ٱلۡمُرۡسَلِينَ','اور یونس بھی پیغمبروں میں سے تھے','And Jonah was indeed one of the messengers','और इसमें शक नहीं कि यूनुस (भी) पैग़म्बरों में से थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,140,'As-Saaffaat','إِذۡ أَبَقَ إِلَى ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ','جب بھاگ کر بھری ہوئی کشتی میں پہنچے','˹Remember˺ when he fled to the overloaded ship','(वह वक्त याद करो) जब यूनुस भाग कर एक भरी हुई कश्ती के पास पहुँचे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,141,'As-Saaffaat','فَسَاهَمَ فَكَانَ مِنَ ٱلۡمُدۡحَضِينَ','اس وقت قرعہ ڈالا تو انہوں نے زک اُٹھائی','Then ˹to save it from sinking,˺ he drew straws ˹with other passengers˺. He lost ˹and was thrown overboard˺','तो (अहले कश्ती ने) कुरआ डाला तो (उनका ही नाम निकला) यूनुस ने ज़क उठायी (और दरिया में गिर पड़े)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,142,'As-Saaffaat','فَٱلۡتَقَمَهُ ٱلۡحُوتُ وَهُوَ مُلِيمࣱ‏','پھر مچھلی نے ان کو نگل لیا اور وہ (قابل) ملامت (کام) کرنے والے تھے','Then the whale engulfed him while he was blameworthy','तो उनको एक मछली निगल गयी और यूनुस खुद (अपनी) मलामत कर रहे थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,143,'As-Saaffaat','فَلَوۡلَآ أَنَّهُۥ كَانَ مِنَ ٱلۡمُسَبِّحِينَ','پھر اگر وہ (خدا کی) پاکی بیان نہ کرتے','Had he not ˹constantly˺ glorified ˹Allah˺','फिर अगर यूनुस (खुदा की) तसबीह (व ज़िक्र) न करते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,144,'As-Saaffaat','لَلَبِثَ فِي بَطۡنِهِۦٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ','تو اس روز تک کہ لوگ دوبارہ زندہ کئے جائیں گے اسی کے پیٹ میں رہتے','he would have certainly remained in its belly until the Day of Resurrection','तो रोज़े क़यामत तक मछली के पेट में रहते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,145,'As-Saaffaat','۞فَنَبَذۡنَٰهُ بِٱلۡعَرَآءِ وَهُوَ سَقِيمࣱ‏','پھر ہم نے ان کو جب کہ وہ بیمار تھے فراخ میدان میں ڈال دیا','But We cast him onto the open ˹shore˺, ˹totally˺ worn out','फिर हमने उनको (मछली के पेट से निकाल कर) एक खुले मैदान में डाल दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,146,'As-Saaffaat','وَأَنۢبَتۡنَا عَلَيۡهِ شَجَرَةࣰ مِّن يَقۡطِينࣲ‏','اور ان پر کدو کا درخت اُگایا','and caused a squash plant to grow over him','और (वह थोड़ी देर में) बीमार निढाल हो गए थे और हमने उन पर साये के लिए एक कद्दू का दरख्त उगा दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,147,'As-Saaffaat','وَأَرۡسَلۡنَٰهُ إِلَىٰ مِاْئَةِ أَلۡفٍ أَوۡ يَزِيدُونَ','اور ان کو لاکھ یا اس سے زیادہ (لوگوں) کی طرف (پیغمبر بنا کر) بھیجا','We ˹later˺ sent him ˹back˺ to ˹his city of˺ at least one hundred thousand people','और (इसके बाद) हमने एक लाख बल्कि (एक हिसाब से) ज्यादा आदमियों की तरफ (पैग़म्बर बना कर भेजा)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,148,'As-Saaffaat','فَـَٔامَنُواْ فَمَتَّعۡنَٰهُمۡ إِلَىٰ حِينࣲ‏','تو وہ ایمان لے آئے سو ہم نے بھی ان کو (دنیا میں) ایک وقت (مقرر) تک فائدے دیتے رہے','who then believed ˹in him˺, so We allowed them enjoyment for a while','तो वह लोग (उन पर) ईमान लाए फिर हमने (भी) एक ख़ास वक्त तक उनको चैन से रखा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,149,'As-Saaffaat','فَٱسۡتَفۡتِهِمۡ أَلِرَبِّكَ ٱلۡبَنَاتُ وَلَهُمُ ٱلۡبَنُونَ','ان سے پوچھو تو کہ بھلا تمہارے پروردگار کے لئے تو بیٹیاں اور ان کے لئے بیٹے','Ask them ˹O Prophet˺ if your Lord has daughters, while the pagans ˹prefer to˺ have sons','तो (ऐ रसूल) उन कुफ्फ़ार से पूछो कि क्या तुम्हारे परवरदिगार के लिए बेटियाँ हैं और उनके लिए बेटे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,150,'As-Saaffaat','أَمۡ خَلَقۡنَا ٱلۡمَلَٰٓئِكَةَ إِنَٰثࣰ ا وَهُمۡ شَٰهِدُونَ','یا ہم نے فرشتوں کو عورتیں بنایا اور وہ (اس وقت) موجود تھے','Or ˹ask them˺ if We created the angels as females right before their eyes','(क्या वाक़ई) हमने फरिश्तों की औरतें बनाया है और ये लोग (उस वक्त) मौजूद थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,151,'As-Saaffaat','أَلَآ إِنَّهُم مِّنۡ إِفۡكِهِمۡ لَيَقُولُونَ','دیکھو یہ اپنی جھوٹ بنائی ہوئی (بات) کہتے ہیں','Indeed, it is one of their ˹outrageous˺ fabrications to say','ख़बरदार (याद रखो कि) ये लोग यक़ीनन अपने दिल से गढ़-गढ़ के कहते हैं कि खुदा औलाद वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,152,'As-Saaffaat','وَلَدَ ٱللَّهُ وَإِنَّهُمۡ لَكَٰذِبُونَ','کہ خدا کے اولاد ہے کچھ شک نہیں کہ یہ جھوٹے ہیں','“Allah has children.” They are simply liars','और ये लोग यक़ीनी झूठे हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,153,'As-Saaffaat','أَصۡطَفَى ٱلۡبَنَاتِ عَلَى ٱلۡبَنِينَ','کیا اس نے بیٹوں کی نسبت بیٹیوں کو پسند کیا ہے؟','Has He chosen daughters over sons','क्या खुदा ने (अपने लिए) बेटियों को बेटों पर तरजीह दी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,154,'As-Saaffaat','مَا لَكُمۡ كَيۡفَ تَحۡكُمُونَ','تم کیسے لوگ ہو، کس طرح کا فیصلہ کرتے ہو','What is the matter with you? How do you judge','(अरे कम्बख्तों) तुम्हें क्या जुनून हो गया है तुम लोग (बैठे-बैठे) कैसा फैसला करते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,155,'As-Saaffaat','أَفَلَا تَذَكَّرُونَ','بھلا تم غور کیوں نہیں کرتے','Will you not then be mindful','तो क्या तुम (इतना भी) ग़ौर नहीं करते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,156,'As-Saaffaat','أَمۡ لَكُمۡ سُلۡطَٰنࣱ مُّبِينࣱ‏','یا تمہارے پاس کوئی صریح دلیل ہے','Or do you have ˹any˺ compelling proof','या तुम्हारे पास (इसकी) कोई वाज़ेए व रौशन दलील है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,157,'As-Saaffaat','فَأۡتُواْ بِكِتَٰبِكُمۡ إِن كُنتُمۡ صَٰدِقِينَ','اگر تم سچے ہو تو اپنی کتاب پیش کرو','Then bring ˹us˺ your scripture, if what you say is true','तो अगर तुम (अपने दावे में) सच्चे हो तो अपनी किताब पेश करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,158,'As-Saaffaat','وَجَعَلُواْ بَيۡنَهُۥ وَبَيۡنَ ٱلۡجِنَّةِ نَسَبࣰ اۚ وَلَقَدۡ عَلِمَتِ ٱلۡجِنَّةُ إِنَّهُمۡ لَمُحۡضَرُونَ','اور انہوں نے خدا میں اور جنوں میں رشتہ مقرر کیا۔ حالانکہ جنات جانتے ہیں کہ وہ (خدا کے سامنے) حاضر کئے جائیں گے','They have also established a ˹marital˺ relationship between Him and the jinn. Yet the jinn ˹themselves˺ know well that such people will certainly be brought ˹for punishment˺','और उन लोगों ने खुदा और जिन्नात के दरमियान रिश्ता नाता मुक़र्रर किया है हालाँकि जिन्नात बखूबी जानते हैं कि वह लोग यक़ीनी (क़यामत में बन्दों की तरह) हाज़िर किए जाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,159,'As-Saaffaat','سُبۡحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ','یہ جو کچھ بیان کرتے ہیں خدا اس سے پاک ہے','Glorified is Allah far above what they claim','ये लोग जो बातें बनाया करते हैं इनसे खुदा पाक साफ़ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,160,'As-Saaffaat','إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ','مگر خدا کے بندگان خالص (مبتلائے عذاب نہیں ہوں گے)','But not the chosen servants of Allah','मगर खुदा के निरे खरे बन्दे (ऐसा नहीं कहते)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,161,'As-Saaffaat','فَإِنَّكُمۡ وَمَا تَعۡبُدُونَ','سو تم اور جن کو تم پوجتے ہو','Surely you ˹pagans˺ and whatever ˹idols˺ you worship','ग़रज़ तुम लोग खुद और तुम्हारे माबूद');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,162,'As-Saaffaat','مَآ أَنتُمۡ عَلَيۡهِ بِفَٰتِنِينَ','خدا کے خلاف بہکا نہیں سکتے','can never lure ˹anyone˺ away from Him','उसके ख़िलाफ (किसी को) बहका नहीं सकते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,163,'As-Saaffaat','إِلَّا مَنۡ هُوَ صَالِ ٱلۡجَحِيمِ','مگر اس کو جو جہنم میں جانے والا ہے','except those ˹destined˺ to burn in Hell','मगर उसको जो जहन्नुम में झोंका जाने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,164,'As-Saaffaat','وَمَا مِنَّآ إِلَّا لَهُۥ مَقَامࣱ مَّعۡلُومࣱ‏','اور (فرشتے کہتے ہیں کہ) ہم میں سے ہر ایک کا ایک مقام مقرر ہے','˹The angels respond,˺ “There is not one of us without an assigned station ˹of worship˺','और फरिश्ते या आइम्मा तो ये कहते हैं कि मैं हर एक का एक दरजा मुक़र्रर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,165,'As-Saaffaat','وَإِنَّا لَنَحۡنُ ٱلصَّآفُّونَ','اور ہم صف باندھے رہتے ہیں','We are indeed the ones lined up in ranks ˹for Allah˺','और हम तो यक़ीनन (उसकी इबादत के लिए) सफ बाँधे खड़े रहते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,166,'As-Saaffaat','وَإِنَّا لَنَحۡنُ ٱلۡمُسَبِّحُونَ','اور (خدائے) پاک (ذات) کا ذکر کرتے رہتے ہیں','And we are indeed the ones ˹constantly˺ glorifying ˹His praise˺.”','और हम तो यक़ीनी (उसकी) तस्बीह पढ़ा करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,167,'As-Saaffaat','وَإِن كَانُواْ لَيَقُولُونَ','اور یہ لوگ کہا کرتے تھے','They certainly used to say','अगरचे ये कुफ्फार (इस्लाम के क़ब्ल) कहा करते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,168,'As-Saaffaat','لَوۡ أَنَّ عِندَنَا ذِكۡرࣰ ا مِّنَ ٱلۡأَوَّلِينَ','کہ اگر ہمارے پاس اگلوں کی کوئی نصیحت (کی کتاب) ہوتی','“If only we had a Reminder like ˹those of˺ earlier peoples','कि अगर हमारे पास भी अगले लोगों का तज़किरा (किसी किताबे खुदा में) होता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,169,'As-Saaffaat','لَكُنَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ','تو ہم خدا کے خالص بندے ہوتے','we would have truly been Allah’s devoted servants.”','तो हम भी खुदा के निरे खरे बन्दे ज़रूर हो जाते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,170,'As-Saaffaat','فَكَفَرُواْ بِهِۦۖ فَسَوۡفَ يَعۡلَمُونَ','لیکن (اب) اس سے کفر کرتے ہیں سو عنقریب ان کو (اس کا نتیجہ) معلوم ہوجائے گا','But ˹now˺ they reject it, so they will soon know','(मगर जब किताब आयी) तो उन लोगों ने उससे इन्कार किया ख़ैर अनक़रीब (उसका नतीजा) उन्हें मालूम हो जाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,171,'As-Saaffaat','وَلَقَدۡ سَبَقَتۡ كَلِمَتُنَا لِعِبَادِنَا ٱلۡمُرۡسَلِينَ','اور اپنے پیغام پہنچانے والے بندوں سے ہمارا وعدہ ہوچکا ہے','Our Word has already gone forth to Our servants, the messengers','और अपने ख़ास बन्दों पैग़म्बरों से हमारी बात पक्की हो चुकी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,172,'As-Saaffaat','إِنَّهُمۡ لَهُمُ ٱلۡمَنصُورُونَ','کہ وہی (مظفرو) منصور ہیں','that they would surely be helped','कि इन लोगों की (हमारी बारगाह से) यक़ीनी मदद की जाएगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,173,'As-Saaffaat','وَإِنَّ جُندَنَا لَهُمُ ٱلۡغَٰلِبُونَ','اور ہمارا لشکر غالب رہے گا','and that Our forces will certainly prevail','और हमारा लश्कर तो यक़ीनन ग़ालिब रहेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,174,'As-Saaffaat','فَتَوَلَّ عَنۡهُمۡ حَتَّىٰ حِينࣲ‏','تو ایک وقت تک ان سے اعراض کئے رہو','So turn away from the deniers for a while ˹O Prophet˺','तो (ऐ रसूल) तुम उनसे एक ख़ास वक्त तक मुँह फेरे रहो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,175,'As-Saaffaat','وَأَبۡصِرۡهُمۡ فَسَوۡفَ يُبۡصِرُونَ','اور انہیں دیکھتے رہو۔ یہ بھی عنقریب (کفر کا انجام) دیکھ لیں گے','You will see ˹what will happen to˺ them, and they too will see','और इनको देखते रहो तो ये लोग अनक़रीब ही (अपना नतीजा) देख लेगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,176,'As-Saaffaat','أَفَبِعَذَابِنَا يَسۡتَعۡجِلُونَ','کیا یہ ہمارے عذاب کے لئے جلدی کر رہے ہیں','Do they ˹really˺ wish to hasten Our punishment','तो क्या ये लोग हमारे अज़ाब की जल्दी कर रहे हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,177,'As-Saaffaat','فَإِذَا نَزَلَ بِسَاحَتِهِمۡ فَسَآءَ صَبَاحُ ٱلۡمُنذَرِينَ','مگر جب وہ ان کے میدان میں آ اُترے گا تو جن کو ڈر سنا دیا گیا تھا ان کے لئے برا دن ہوگا','Yet when it descends upon them: how evil will that morning be for those who had been warned','फिर जब (अज़ाब) उनकी अंगनाई में उतर पडेग़ा तो जो लोग डराए जा चुके हैं उनकी भी क्या बुरी सुबह होगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,178,'As-Saaffaat','وَتَوَلَّ عَنۡهُمۡ حَتَّىٰ حِينࣲ‏','اور ایک وقت تک ان سے منہ پھیرے رہو','And turn away from them for a while','और उन लोगों से एक ख़ास वक्त तक मुँह फेरे रहो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,179,'As-Saaffaat','وَأَبۡصِرۡ فَسَوۡفَ يُبۡصِرُونَ','اور دیکھتے رہو یہ بھی عنقریب (نتیجہ) دیکھ لیں گے','You will see, and they too will see','और देखते रहो ये लोग तो खुद अनक़रीब ही अपना अन्जाम देख लेगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,180,'As-Saaffaat','سُبۡحَٰنَ رَبِّكَ رَبِّ ٱلۡعِزَّةِ عَمَّا يَصِفُونَ','یہ جو کچھ بیان کرتے ہیں تمہارا پروردگار جو صاحب عزت ہے اس سے (پاک ہے)','Glorified is your Lord—the Lord of Honour and Power—above what they claim','ये लोग जो बातें (खुदा के बारे में) बनाया करते हैं उनसे तुम्हारा परवरदिगार इज्ज़त का मालिक पाक साफ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,181,'As-Saaffaat','وَسَلَٰمٌ عَلَى ٱلۡمُرۡسَلِينَ','اور پیغمبروں پر سلام','Peace be upon the messengers','और पैग़म्बरों पर (दुरूद) सलाम हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (37,182,'As-Saaffaat','وَٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ','اور سب طرح کی تعریف خدائے رب العالمین کو (سزاوار) ہے','And praise be to Allah—Lord of all worlds','और कुल तारीफ खुदा ही के लिए सज़ावार हैं जो सारे जहाँन का पालने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,1,'Saad','صٓۚ وَٱلۡقُرۡءَانِ ذِي ٱلذِّكۡرِ','ص۔ قسم ہے اس قرآن کی جو نصیحت دینے والا ہے (کہ تم حق پر ہو)','Ṣãd. By the Quran, full of reminders','सआद नसीहत करने वाले कुरान की क़सम (तुम बरहक़ नबी हो)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,2,'Saad','بَلِ ٱلَّذِينَ كَفَرُواْ فِي عِزَّةࣲ وَشِقَاقࣲ‏','مگر جو لوگ کافر ہیں وہ غرور اور مخالفت میں ہیں','˹This is the truth,˺ yet the disbelievers are ˹entrenched˺ in arrogance and opposition','मगर ये कुफ्फ़ार (ख्वाहमख्वाह) तकब्बुर और अदावत में (पड़े अंधे हो रहें हैं)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,3,'Saad','كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّن قَرۡنࣲ فَنَادَواْ وَّلَاتَ حِينَ مَنَاصࣲ‏','ہم نے ان سے پہلے بہت سی اُمتوں کو ہلاک کردیا تو وہ (عذاب کے وقت) لگے فریاد کرنے اور وہ رہائی کا وقت نہیں تھا','˹Imagine˺ how many peoples We destroyed before them, and they cried out when it was too late to escape','हमने उन से पहले कितने गिरोह हलाक कर डाले तो (अज़ाब के वक्त) ये लोग चीख़ उठे मगर छुटकारे का वक्त ही न रहा था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,4,'Saad','وَعَجِبُوٓاْ أَن جَآءَهُم مُّنذِرࣱ مِّنۡهُمۡۖ وَقَالَ ٱلۡكَٰفِرُونَ هَٰذَا سَٰحِرࣱ كَذَّابٌ','اور انہوں نے تعجب کیا کہ ان کے پاس ان ہی میں سے ہدایت کرنے والا آیا اور کافر کہنے لگے کہ یہ تو جادوگر ہے جھوٹا','Now, the pagans are astonished that a warner has come to them from among themselves. And the disbelievers say, “This is a magician, a total liar','और उन लोगों ने इस बात से ताज्जुब किया कि उन्हीं में का (अज़ाबे खुदा से) एक डरानेवाला (पैग़म्बर) उनके पास आया और काफिर लोग कहने लगे कि ये तो बड़ा (खिलाड़ी) जादूगर और पक्का झूठा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,5,'Saad','أَجَعَلَ ٱلۡأٓلِهَةَ إِلَٰهࣰ ا وَٰحِدًاۖ إِنَّ هَٰذَا لَشَيۡءٌ عُجَابࣱ‏','کیا اس نے اتنے معبودوں کی جگہ ایک ہی معبود بنا دیا۔ یہ تو بڑی عجیب بات ہے','Has he reduced ˹all˺ the gods to One God? Indeed, this is something totally astonishing.”','भला (देखो तो) उसने तमाम माबूदों को (मटियामेट करके बस) एक ही माबूद क़ायम रखा ये तो यक़ीनी बड़ी ताज्जुब खेज़ बात है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,6,'Saad','وَٱنطَلَقَ ٱلۡمَلَأُ مِنۡهُمۡ أَنِ ٱمۡشُواْ وَٱصۡبِرُواْ عَلَىٰٓ ءَالِهَتِكُمۡۖ إِنَّ هَٰذَا لَشَيۡءࣱ يُرَادُ','تو ان میں جو معزز تھے وہ چل کھڑے ہوئے (اور بولے) کہ چلو اور اپنے معبودوں (کی پوجا) پر قائم رہو۔ بےشک یہ ایسی بات ہے جس سے (تم پر شرف وفضلیت) مقصود ہے','The chiefs among them went forth saying, “Carry on, and stand firm in devotion to your gods. Certainly this is just a scheme ˹for power˺','और उनमें से चन्द रवादार लोग (मजलिस व अज़ा से) ये (कह कर) चल खड़े हुए कि (यहाँ से) चल दो और अपने माबूदों की इबादत पर जमे रहो यक़ीनन इसमें (उसकी) कुछ ज़ाती ग़रज़ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,7,'Saad','مَا سَمِعۡنَا بِهَٰذَا فِي ٱلۡمِلَّةِ ٱلۡأٓخِرَةِ إِنۡ هَٰذَآ إِلَّا ٱخۡتِلَٰقٌ','یہ پچھلے مذہب میں ہم نے کبھی سنی ہی نہیں۔ یہ بالکل بنائی ہوئی بات ہے','We have never heard of this in the previous faith. This is nothing but a fabrication','हम लोगों ने तो ये बात पिछले दीन में कभी सुनी भी नहीं हो न हो ये उसकी मन गढ़ंत है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,8,'Saad','أَءُنزِلَ عَلَيۡهِ ٱلذِّكۡرُ مِنۢ بَيۡنِنَاۚ بَلۡ هُمۡ فِي شَكࣲّ مِّن ذِكۡرِيۚ بَل لَّمَّا يَذُوقُواْ عَذَابِ','کیا ہم سب میں سے اسی پر نصیحت (کی کتاب) اُتری ہے؟ (نہیں) بلکہ یہ میری نصیحت کی کتاب سے شک میں ہیں۔ بلکہ انہوں نے ابھی میرے عذاب کا مزہ نہیں چکھا','Has the Reminder been revealed ˹only˺ to him out of ˹all of˺ us?” In fact, they are ˹only˺ in doubt of My ˹revealed˺ Reminder. In fact, ˹they do so because˺ they have not yet tasted My punishment','क्या हम सब लोगों में बस (मोहम्मद ही क़ाबिल था कि) उस पर कुरान नाज़िल हुआ, नहीं बात ये है कि इनके (सिरे से) मेरे कलाम ही में शक है कि मेरा है या नहीं बल्कि असल ये है कि इन लोगों ने अभी तक अज़ाब के मज़े नहीं चखे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,9,'Saad','أَمۡ عِندَهُمۡ خَزَآئِنُ رَحۡمَةِ رَبِّكَ ٱلۡعَزِيزِ ٱلۡوَهَّابِ','کیا ان کے پاس تمہارے پروردگار کی رحمت کے خزانے ہیں جو غالب اور بہت عطا کرنے والا ہے','Or ˹is it because˺ they possess the treasuries of the mercy of your Lord—the Almighty, the Giver ˹of all bounties˺','(इस वजह से ये शरारत है) (ऐ रसूल) तुम्हारे ज़बरदस्त फ़य्याज़ परवरदिगार के रहमत के ख़ज़ाने इनके पास हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,10,'Saad','أَمۡ لَهُم مُّلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَاۖ فَلۡيَرۡتَقُواْ فِي ٱلۡأَسۡبَٰبِ','یا آسمانوں اور زمین اور جو کچھ ان میں ہے ان (سب) پر ان ہی کی حکومت ہے۔ تو چاہیئے کہ رسیاں تان کر (آسمانوں) پر چڑھ جائیں','Or ˹is it because˺ the kingdom of the heavens and the earth and everything in between belongs to them? Let them then climb their way ˹to heaven, if their claim is true˺','या सारे आसमान व ज़मीन और उन दोनों के दरमियान की सलतनत इन्हीं की ख़ास है तब इनको चाहिए कि रास्ते या सीढियाँ लगाकर (आसमान पर) चढ़ जाएँ और इन्तेज़ाम करें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,11,'Saad','جُندࣱ مَّا هُنَالِكَ مَهۡزُومࣱ مِّنَ ٱلۡأَحۡزَابِ','یہاں شکست کھائے ہوئے گروہوں میں سے یہ بھی ایک لشکر ہے','This is just another ˹enemy˺ force bound for defeat out there','(ऐ रसूल उन पैग़म्बरों के साथ झगड़ने वाले) गिरोहों में से यहाँ तुम्हारे मुक़ाबले में भी एक लशकर है जो शिकस्त खाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,12,'Saad','كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحࣲ وَعَادࣱ وَفِرۡعَوۡنُ ذُو ٱلۡأَوۡتَادِ','ان سے پہلے نوح کی قوم اور عاد اور میخوں والا فرعون (اور اس کی قوم کے لوگ) بھی جھٹلا چکے ہیں','Before them, the people of Noah denied ˹the truth˺, as did ’Âd, Pharaoh of the mighty structures','उनसे पहले नूह की क़ौम और आद और फिरऔन मेंख़ों वाला');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,13,'Saad','وَثَمُودُ وَقَوۡمُ لُوطࣲ وَأَصۡحَٰبُ لۡـَٔيۡكَةِۚ أُوْلَٰٓئِكَ ٱلۡأَحۡزَابُ','اور ثمود اور لوط کی قوم اور بن کے رہنے والے بھی۔ یہی وہ گروہ ہیں','Thamûd, the people of Lot, and the residents of the Forest. These were ˹all˺ enemy forces','और समूद और लूत की क़ौम और जंगल के रहने वाले (क़ौम शुऐब ये सब पैग़म्बरों को) झुठला चुकी हैं यही वह गिरोह है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,14,'Saad','إِن كُلٌّ إِلَّا كَذَّبَ ٱلرُّسُلَ فَحَقَّ عِقَابِ','(ان) سب نے پیغمبروں کو جھٹلایا تو میرا عذاب (ان پر) آ واقع ہوا','Each rejected their messenger, so My punishment was justified','(जो शिकस्त खा चुके) सब ही ने तो पैग़म्बरों को झुठलाया तो हमारा अज़ाब ठीक आ नाज़िल हुआ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,15,'Saad','وَمَا يَنظُرُ هَٰٓؤُلَآءِ إِلَّا صَيۡحَةࣰ وَٰحِدَةࣰ مَّا لَهَا مِن فَوَاقࣲ‏','اور یہ لوگ تو صرف ایک زور کی آواز کا جس میں (شروع ہوئے پیچھے) کچھ وقفہ نہیں ہوگا، انتظار کرتے ہیں','These ˹pagans˺ are awaiting nothing but a single Blast that cannot be stopped','और ये (काफिर) लोग बस एक चिंघाड़ (सूर के मुन्तज़िर हैं जो फिर उन्हें) चश्में ज़दन की मोहलत न देगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,16,'Saad','وَقَالُواْ رَبَّنَا عَجِّل لَّنَا قِطَّنَا قَبۡلَ يَوۡمِ ٱلۡحِسَابِ','اور کہتے ہیں کہ اے ہمارے پروردگار ہم کو ہمارا حصہ حساب کے دن سے پہلے ہی دے دے','They say ˹mockingly˺, “Our Lord! Hasten for us our share ˹of the punishment˺ before the Day of Reckoning.”','और ये लोग (मज़ाक से) कहते हैं कि परवरदिगार हिसाब के दिन (क़यामत के) क़ब्ल ही (जो) हमारी क़िस्मत को लिखा (हो) हमें जल्दी दे दे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,17,'Saad','ٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَٱذۡكُرۡ عَبۡدَنَا دَاوُۥدَ ذَا ٱلۡأَيۡدِۖ إِنَّهُۥٓ أَوَّابٌ','(اے پیغمبر) یہ جو کچھ کہتے ہیں اس پر صبر کرو۔ اور ہمارے بندے داؤد کو یاد کرو جو صاحب قوت تھے (اور) بےشک وہ رجوع کرنے والے تھے','Be patient ˹O Prophet˺ with what they say. And remember Our servant, David, the man of strength. Indeed, he ˹constantly˺ turned ˹to Allah˺','(ऐ रसूल) जैसी जैसी बातें ये लोग करते हैं उन पर सब्र करो और हमारे बन्दे दाऊद को याद करो जो बड़े कूवत वाले थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,18,'Saad','إِنَّا سَخَّرۡنَا ٱلۡجِبَالَ مَعَهُۥ يُسَبِّحۡنَ بِٱلۡعَشِيِّ وَٱلۡإِشۡرَاقِ','ہم نے پہاڑوں کو ان کے زیر فرمان کردیا تھا کہ صبح وشام ان کے ساتھ (خدائے) پاک (کا) ذکر کرتے تھے','We truly subjected the mountains to hymn ˹Our praises˺ along with him in the evening and after sunrise','बेशक वह हमारी बारगाह में बड़े रूजू करने वाले थे हमने पहाड़ों को भी ताबेदार बना दिया था कि उनके साथ सुबह और शाम (खुदा की) तस्बीह करते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,19,'Saad','وَٱلطَّيۡرَ مَحۡشُورَةࣰۖ كُلࣱّ لَّهُۥٓ أَوَّابࣱ‏','اور پرندوں کو بھی کہ جمع رہتے تھے۔ سب ان کے فرمانبردار تھے','And ˹We subjected˺ the birds, flocking together. All turned to him ˹echoing his hymns˺','और परिन्दे भी (यादे खुदा के वक्त सिमट) आते और उनके फरमाबरदार थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,20,'Saad','وَشَدَدۡنَا مُلۡكَهُۥ وَءَاتَيۡنَٰهُ ٱلۡحِكۡمَةَ وَفَصۡلَ ٱلۡخِطَابِ','اور ہم نے ان کی بادشاہی کو مستحکم کیا اور ان کو حکمت عطا کی اور (خصومت کی) بات کا فیصلہ (سکھایا)','We strengthened his kingship, and gave him wisdom and sound judgment','और हमने उनकी सल्तनत को मज़बूत कर दिया और हमने उनको हिकमत और बहस के फैसले की कूवत अता फरमायी थी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,21,'Saad','۞وَهَلۡ أَتَىٰكَ نَبَؤُاْ ٱلۡخَصۡمِ إِذۡ تَسَوَّرُواْ ٱلۡمِحۡرَابَ','بھلا تمہارے پاس ان جھگڑنے والوں کی بھی خبر آئی ہے جب وہ دیوار پھاند کر عبادت خانے میں داخل ہوئے','Has the story of the two plaintiffs, who scaled the ˹wall of David’s˺ sanctuary, reached you ˹O Prophet˺','(ऐ रसूल) क्या तुम तक उन दावेदारों की भी ख़बर पहुँची है कि जब वह हुजरे (इबादत) की दीवार फाँद पडे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,22,'Saad','إِذۡ دَخَلُواْ عَلَىٰ دَاوُۥدَ فَفَزِعَ مِنۡهُمۡۖ قَالُواْ لَا تَخَفۡۖ خَصۡمَانِ بَغَىٰ بَعۡضُنَا عَلَىٰ بَعۡضࣲ فَٱحۡكُم بَيۡنَنَا بِٱلۡحَقِّ وَلَا تُشۡطِطۡ وَٱهۡدِنَآ إِلَىٰ سَوَآءِ ٱلصِّرَٰطِ','جس وقت وہ داؤد کے پاس آئے تو وہ ان سے گھبرا گئے انہوں نے کہا کہ خوف نہ کیجیئے۔ ہم دونوں کا ایک مقدمہ ہے کہ ہم میں سے ایک نے دوسرے پر زیادتی کی ہے تو آپ ہم میں انصاف کا فیصلہ کر دیجیئے اور بےانصافی نہ کیجیئے گا اور ہم کو سیدھا رستہ دکھا دیجیئے','When they came into David’s presence, he was startled by them. They said, “Have no fear. ˹We are merely˺ two in a dispute: one of us has wronged the other. So judge between us with truth—do not go beyond ˹it˺—and guide us to the right way','(और) जब दाऊद के पास आ खड़े हुए तो वह उनसे डर गए उन लोगों ने कहा कि आप डरें नहीं (हम दोनों) एक मुक़द्दमें के फ़रीकैन हैं कि हम में से एक ने दूसरे पर ज्यादती की है तो आप हमारे दरमियान ठीक-ठीक फैसला कर दीजिए और इन्साफ से ने गुज़रिये और हमें सीधी राह दिखा दीजिए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,23,'Saad','إِنَّ هَٰذَآ أَخِي لَهُۥ تِسۡعࣱ وَتِسۡعُونَ نَعۡجَةࣰ وَلِيَ نَعۡجَةࣱ وَٰحِدَةࣱ فَقَالَ أَكۡفِلۡنِيهَا وَعَزَّنِي فِي ٱلۡخِطَابِ','(کیفیت یہ ہے کہ) یہ میرا بھائی ہے اس کے (ہاں) ننانوے دنبیاں ہیں اور میرے (پاس) ایک دُنبی ہے۔ یہ کہتا ہے کہ یہ بھی میرے حوالے کردے اور گفتگو میں مجھ پر زبردستی کرتا ہے','This is my brother. He has ninety-nine sheep while I have ˹only˺ one. ˹Still˺ he asked me to give it up to him, overwhelming me with ˹his˺ argument.”','(मुराद ये हैं कि) ये (शख्स) मेरा भाई है और उसके पास निनान्नवे दुम्बियाँ हैं और मेरे पास सिर्फ एक दुम्बी है उस पर भी ये मुझसे कहता है कि ये दुम्बी भी मुझी को दे दें और बातचीत में मुझ पर सख्ती करता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,24,'Saad','قَالَ لَقَدۡ ظَلَمَكَ بِسُؤَالِ نَعۡجَتِكَ إِلَىٰ نِعَاجِهِۦۖ وَإِنَّ كَثِيرࣰ ا مِّنَ ٱلۡخُلَطَآءِ لَيَبۡغِي بَعۡضُهُمۡ عَلَىٰ بَعۡضٍ إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَقَلِيلࣱ مَّا هُمۡۗ وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّٰهُ فَٱسۡتَغۡفَرَ رَبَّهُۥ وَخَرَّۤ رَاكِعࣰ اۤ وَأَنَابَ۩','انہوں نے کہا کہ یہ جو تیری دنبی مانگتا ہے کہ اپنی دنبیوں میں ملالے بےشک تجھ پر ظلم کرتا ہے۔ اور اکثر شریک ایک دوسرے پر زیادتی ہی کیا کرتے ہیں۔ ہاں جو ایمان لائے اور عمل نیک کرتے رہے اور ایسے لوگ بہت کم ہیں۔ اور داؤد نے خیال کیا کہ (اس واقعے سے) ہم نے ان کو آزمایا ہے تو انہوں نے اپنے پروردگار سے مغفرت مانگی اور جھک کر گڑ پڑے اور (خدا کی طرف) رجوع کیا','David ˹eventually˺ ruled, “He has definitely wronged you in demanding ˹to add˺ your sheep to his. And certainly many partners wrong each other, except those who believe and do good—but how few are they!” Then David realized that We had tested him so he asked for his Lord’s forgiveness, fell down in prostration, and turned ˹to Him in repentance˺','दाऊद ने (बग़ैर इसके कि मुदा आलैह से कुछ पूछें) कह दिया कि ये जो तेरी दुम्बी माँग कर अपनी दुम्बियों में मिलाना चाहता है तो ये तुझ पर ज़ुल्म करता है और अक्सर शुरका (की) यकीनन (ये हालत है कि) एक दूसरे पर जुल्म किया करते हैं मगर जिन लोगों ने (सच्चे दिल से) ईमान कुबूल किया और अच्छे (अच्छे) काम किए (वह ऐसा नहीं करते) और ऐसे लोग बहुत ही कम हैं (ये सुनकर दोनों चल दिए) और अब दाऊद ने समझा कि हमने उनका इमितेहान लिया (और वह ना कामयाब रहे) फिर तो अपने परवरदिगार से बख्शिश की दुआ माँगने लगे और सजदे में गिर पड़े और (मेरी) तरफ रूजू की (24) (सजदा)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,25,'Saad','فَغَفَرۡنَا لَهُۥ ذَٰلِكَۖ وَإِنَّ لَهُۥ عِندَنَا لَزُلۡفَىٰ وَحُسۡنَ مَـَٔابࣲ‏','تو ہم نے ان کو بخش دیا۔ اور بےشک ان کے لئے ہمارے ہاں قرب اور عمدہ مقام ہے','So We forgave that for him. And he will indeed have ˹a status of˺ closeness to Us and an honourable destination','तो हमने उनकी वह ग़लती माफ कर दी और इसमें शक नहीं कि हमारी बारगाह में उनका तक़र्रुब और अन्जाम अच्छा हुआ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,26,'Saad','يَٰدَاوُۥدُ إِنَّا جَعَلۡنَٰكَ خَلِيفَةࣰ فِي ٱلۡأَرۡضِ فَٱحۡكُم بَيۡنَ ٱلنَّاسِ بِٱلۡحَقِّ وَلَا تَتَّبِعِ ٱلۡهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِۚ إِنَّ ٱلَّذِينَ يَضِلُّونَ عَن سَبِيلِ ٱللَّهِ لَهُمۡ عَذَابࣱ شَدِيدُۢ بِمَا نَسُواْ يَوۡمَ ٱلۡحِسَابِ','اے داؤد ہم نے تم کو زمین میں بادشاہ بنایا ہے تو لوگوں میں انصاف کے فیصلے کیا کرو اور خواہش کی پیروی نہ کرنا کہ وہ تمہیں خدا کے رستے سے بھٹکا دے گی۔ جو لوگ خدا کے رستے سے بھٹکتے ہیں ان کے لئے سخت عذاب (تیار) ہے کہ انہوں نے حساب کے دن کو بھلا دیا','˹We instructed him:˺ “O David! We have surely made you an authority in the land, so judge between people with truth. And do not follow ˹your˺ desires or they will lead you astray from Allah’s Way. Surely those who go astray from Allah’s Way will suffer a severe punishment for neglecting the Day of Reckoning.”','(हमने फरमाया) ऐ दाऊद हमने तुमको ज़मीन में (अपना) नाएब क़रार दिया तो तुम लोगों के दरमियान बिल्कुल ठीक फैसला किया करो और नफ़सियानी ख्वाहिश की पैरवी न करो बसा ये पीरों तुम्हें ख़ुदा की राह से बहका देगी इसमें शक नहीं कि जो लोग खुदा की राह में भटकते हैं उनकी बड़ी सख्त सज़ा होगी क्योंकि उन लोगों ने हिसाब के दिन (क़यामत) को भुला दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,27,'Saad','وَمَا خَلَقۡنَا ٱلسَّمَآءَ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا بَٰطِلࣰ اۚ ذَٰلِكَ ظَنُّ ٱلَّذِينَ كَفَرُواْۚ فَوَيۡلࣱ لِّلَّذِينَ كَفَرُواْ مِنَ ٱلنَّارِ','اور ہم نے آسمان اور زمین کو اور جو کائنات ان میں ہے اس کو خالی از مصلحت نہیں پیدا کیا۔ یہ ان کا گمان ہے جو کافر ہیں۔ سو کافروں کے لئے دوزخ کا عذاب ہے','We have not created the heavens and earth and everything in between without purpose—as the disbelievers think. So woe to the disbelievers because of the Fire','और हमने आसमान और ज़मीन और जो चीज़ें उन दोनों के दरमियान हैं बेकार नहीं पैदा किया ये उन लोगों का ख्याल है जो काफ़िर हो बैठे तो जो लोग दोज़ख़ के मुनकिर हैं उन पर अफ़सोस है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,28,'Saad','أَمۡ نَجۡعَلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ كَٱلۡمُفۡسِدِينَ فِي ٱلۡأَرۡضِ أَمۡ نَجۡعَلُ ٱلۡمُتَّقِينَ كَٱلۡفُجَّارِ','جو لوگ ایمان لائے اور عمل نیک کرتے رہے۔ کیا ان کو ہم ان کی طرح کر دیں گے جو ملک میں فساد کرتے ہیں۔ یا پرہیزگاروں کو بدکاروں کی طرح کر دیں گے','Or should We treat those who believe and do good like those who make mischief throughout the land? Or should We treat the righteous like the wicked','क्या जिन लोगों ने ईमान कुबूल किया और अच्छे-अच्छे काम किए उनको हम (उन लोगों के बराबर) कर दें जो रूए ज़मीन में फसाद फैलाया करते हैं या हम परहेज़गारों को मिसल बदकारों के बना दें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,29,'Saad','كِتَٰبٌ أَنزَلۡنَٰهُ إِلَيۡكَ مُبَٰرَكࣱ لِّيَدَّبَّرُوٓاْ ءَايَٰتِهِۦ وَلِيَتَذَكَّرَ أُوْلُواْ ٱلۡأَلۡبَٰبِ','(یہ) کتاب جو ہم نے تم پر نازل کی ہے بابرکت ہے تاکہ لوگ اس کی آیتوں میں غور کریں اور تاکہ اہل عقل نصیحت پکڑیں','˹This is˺ a blessed Book which We have revealed to you ˹O Prophet˺ so that they may contemplate its verses, and people of reason may be mindful','(ऐ रसूल) किताब (कुरान) जो हमने तुम्हारे पास नाज़िल की है (बड़ी) बरकत वाली है ताकि लोग इसकी आयतों में ग़ौर करें और ताकि अक्ल वाले नसीहत हासिल करें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,30,'Saad','وَوَهَبۡنَا لِدَاوُۥدَ سُلَيۡمَٰنَۚ نِعۡمَ ٱلۡعَبۡدُ إِنَّهُۥٓ أَوَّابٌ','اور ہم نے داؤد کو سلیمان عطا کئے۔ بہت خوب بندے (تھے اور) وہ (خدا کی طرف) رجوع کرنے والے تھے','And We blessed David with Solomon—what an excellent servant ˹he was˺! Indeed, he ˹constantly˺ turned ˹to Allah˺','और हमने दाऊद को सुलेमान (सा बेटा) अता किया (सुलेमान भी) क्या अच्छे बन्दे थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,31,'Saad','إِذۡ عُرِضَ عَلَيۡهِ بِٱلۡعَشِيِّ ٱلصَّٰفِنَٰتُ ٱلۡجِيَادُ','جب ان کے سامنے شام کو خاصے کے گھوڑے پیش کئے گئے','˹Remember˺ when the well-trained, swift horses were paraded before him in the evening','बेशक वह हमारी तरफ रूजू करने वाले थे इत्तोफाक़न एक दफ़ा तीसरे पहर को ख़ासे के असील घोड़े उनके सामने पेश किए गए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,32,'Saad','فَقَالَ إِنِّيٓ أَحۡبَبۡتُ حُبَّ ٱلۡخَيۡرِ عَن ذِكۡرِ رَبِّي حَتَّىٰ تَوَارَتۡ بِٱلۡحِجَابِ','تو کہنے لگے کہ میں نے اپنے پروردگار کی یاد سے (غافل ہو کر) مال کی محبت اختیار کی۔ یہاں تک کہ (آفتاب) پردے میں چھپ گیا','He then proclaimed, “I am truly in love with ˹these˺ fine things out of remembrance for Allah,” until they went out of sight','तो देखने में उलझे के नवाफिल में देर हो गयी जब याद आया तो बोले कि मैंने अपने परवरदिगार की याद पर माल की उलफ़त को तरजीह दी यहाँ तक कि आफ़ताब (मग़रिब के) पर्दे में छुप गया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,33,'Saad','رُدُّوهَا عَلَيَّۖ فَطَفِقَ مَسۡحَۢا بِٱلسُّوقِ وَٱلۡأَعۡنَاقِ','(بولے کہ) ان کو میرے پاس واپس لے آؤ۔ پھر ان کی ٹانگوں اور گردنوں پر ہاتھ پھیرنے لگے','˹He ordered,˺ “Bring them back to me!” Then he began to rub down their legs and necks','(तो बोले अच्छा) इन घोड़ों को मेरे पास वापस लाओ (जब आए) तो (देर के कफ्फ़ारा में) घोड़ों की टाँगों और गर्दनों पर हाथ फेर (काट) ने लगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,34,'Saad','وَلَقَدۡ فَتَنَّا سُلَيۡمَٰنَ وَأَلۡقَيۡنَا عَلَىٰ كُرۡسِيِّهِۦ جَسَدࣰ ا ثُمَّ أَنَابَ','اور ہم نے سلیمان کی آزمائش کی اور ان کے تخت پر ایک دھڑ ڈال دیا پھر انہوں نے (خدا کی طرف) رجوع کیا','And indeed, We tested Solomon, placing a ˹deformed˺ body on his throne, then he turned ˹to Allah in repentance˺','और हमने सुलेमान का इम्तेहान लिया और उनके तख्त पर एक बेजान धड़ लाकर गिरा दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,35,'Saad','قَالَ رَبِّ ٱغۡفِرۡ لِي وَهَبۡ لِي مُلۡكࣰ ا لَّا يَنۢبَغِي لِأَحَدࣲ مِّنۢ بَعۡدِيٓۖ إِنَّكَ أَنتَ ٱلۡوَهَّابُ','(اور) دعا کی کہ اے پروردگار مجھے مغفرت کر اور مجھ کو ایسی بادشاہی عطا کر کہ میرے بعد کسی کو شایاں نہ ہو۔ بےشک تو بڑا عطا فرمانے والا ہے','He prayed, “My Lord! Forgive me, and grant me an authority that will never be matched by anyone after me. You are indeed the Giver ˹of all bounties˺.”','फिर (सुलेमान ने मेरी तरफ) रूजू की (और) कहा परवरदिगार मुझे बख्श दे और मुझे वह मुल्क अता फरमा जो मेरे बाद किसी के वास्ते शायाँह न हो इसमें तो शक नहीं कि तू बड़ा बख्शने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,36,'Saad','فَسَخَّرۡنَا لَهُ ٱلرِّيحَ تَجۡرِي بِأَمۡرِهِۦ رُخَآءً حَيۡثُ أَصَابَ','پھر ہم نے ہوا کو ان کے زیرفرمان کردیا کہ جہاں وہ پہنچنا چاہتے ان کے حکم سے نرم نرم چلنے لگتی','So We subjected to him the wind, blowing gently at his command to wherever he pleased','तो हमने हवा को उनका ताबेए कर दिया कि जहाँ वह पहुँचना चाहते थे उनके हुक्म के मुताबिक़ धीमी चाल चलती थी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,37,'Saad','وَٱلشَّيَٰطِينَ كُلَّ بَنَّآءࣲ وَغَوَّاصࣲ‏','اَور دیووں کو بھی (ان کے زیرفرمان کیا) وہ سب عمارتیں بنانے والے اور غوطہ مارنے والے تھے','And ˹We subjected to him˺ every builder and diver of the jinn','और (इसी तरह) जितने शयातीन (देव) इमारत बनाने वाले और ग़ोता लगाने वाले थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,38,'Saad','وَءَاخَرِينَ مُقَرَّنِينَ فِي ٱلۡأَصۡفَادِ','اور اَوروں کو بھی جو زنجیروں میں جکڑے ہوئے تھے','and others bound together in chains','सबको (ताबेए कर दिया और इसके अलावा) दूसरे देवों को भी जो ज़ंज़ीरों में जकड़े हुए थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,39,'Saad','هَٰذَا عَطَآؤُنَا فَٱمۡنُنۡ أَوۡ أَمۡسِكۡ بِغَيۡرِ حِسَابࣲ‏','(ہم نے کہا) یہ ہماری بخشش ہے (چاہو) تو احسان کرو یا (چاہو تو) رکھ چھوڑو (تم سے) کچھ حساب نہیں ہے','˹Allah said,˺ “This is Our gift, so give or withhold ˹as you wish˺, never to be called to account.”','ऐ सुलेमान ये हमारी बेहिसाब अता है पस (उसे लोगों को देकर) एहसान करो या (सब) अपने ही पास रखो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,40,'Saad','وَإِنَّ لَهُۥ عِندَنَا لَزُلۡفَىٰ وَحُسۡنَ مَـَٔابࣲ‏','اور بےشک ان کے لئے ہمارے ہاں قُرب اور عمدہ مقام ہے','And he will indeed have ˹a status of˺ closeness to Us and an honourable destination','और इसमें शक नहीं कि सुलेमान की हमारी बारगाह में कुर्ब व मज़ेलत और उमदा जगह है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,41,'Saad','وَٱذۡكُرۡ عَبۡدَنَآ أَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلشَّيۡطَٰنُ بِنُصۡبࣲ وَعَذَابٍ','اور ہمارے بندے ایوب کو یاد کرو جب انہوں نے اپنے رب کو پکارا کہ (بار الہٰا) شیطان نے مجھ کو ایذا اور تکلیف دے رکھی ہے','And remember Our servant Job, when he cried out to his Lord, “Satan has afflicted me with distress and suffering.”','और (ऐ रसूल) हमारे (ख़ास) बन्दे अय्यूब को याद करो जब उन्होंने अपने परवरगिार से फरियाद की कि मुझको शैतान ने बहुत अज़ीयत और तकलीफ पहुँचा रखी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,42,'Saad','ٱرۡكُضۡ بِرِجۡلِكَۖ هَٰذَا مُغۡتَسَلُۢ بَارِدࣱ وَشَرَابࣱ‏','(ہم نے کہا کہ زمین پر) لات مارو (دیکھو) یہ (چشمہ نکل آیا) نہانے کو ٹھنڈا اور پینے کو (شیریں)','˹We responded,˺ “Stomp your foot: ˹now˺ here is a cool ˹and refreshing˺ spring for washing and drinking.”','तो हमने कहा कि अपने पाँव से (ज़मीन को) ठुकरा दो और चश्मा निकाला तो हमने कहा (ऐ अय्यूब) तुम्हारे नहाने और पीने के वास्ते ये ठन्डा पानी (हाज़िर) है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,43,'Saad','وَوَهَبۡنَا لَهُۥٓ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةࣰ مِّنَّا وَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ','اور ہم نے ان کو اہل و عیال اور ان کے ساتھ ان کے برابر اور بخشے۔ (یہ) ہماری طرف سے رحمت اور عقل والوں کے لئے نصیحت تھی','And We gave him back his family, twice as many, as a mercy from Us and a lesson for people of reason','और हमने उनको और उनके लड़के वाले और उनके साथ उतने ही और अपनी ख़ास मेहरबानी से अता किए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,44,'Saad','وَخُذۡ بِيَدِكَ ضِغۡثࣰ ا فَٱضۡرِب بِّهِۦ وَلَا تَحۡنَثۡۗ إِنَّا وَجَدۡنَٰهُ صَابِرࣰ اۚ نِّعۡمَ ٱلۡعَبۡدُ إِنَّهُۥٓ أَوَّابࣱ‏','اور اپنے ہاتھ میں جھاڑو لو اور اس سے مارو اور قسم نہ توڑو۔ بےشک ہم نے ان کو ثابت قدم پایا۔ بہت خوب بندے تھے بےشک وہ رجوع کرنے والے تھے','˹And We said to him,˺ “Take in your hand a bundle of grass, and strike ˹your wife˺ with it, and do not break your oath.” We truly found him patient. What an excellent servant ˹he was˺! Indeed, he ˹constantly˺ turned ˹to Allah˺','और अक्लमंदों के लिए इबरत व नसीहत (क़रार दी) और हमने कहा ऐ अय्यूब तुम अपने हाथ से सींको का मट्ठा लो (और उससे अपनी बीवी को) मारो अपनी क़सम में झूठे न बनो हमने कहा अय्यूब को यक़ीनन साबिर पाया वह क्या अच्छे बन्दे थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,45,'Saad','وَٱذۡكُرۡ عِبَٰدَنَآ إِبۡرَٰهِيمَ وَإِسۡحَٰقَ وَيَعۡقُوبَ أُوْلِي ٱلۡأَيۡدِي وَٱلۡأَبۡصَٰرِ','اور ہمارے بندوں ابراہیم اور اسحاق اور یعقوب کو یاد کرو جو ہاتھوں والے اور آنکھوں والے تھے','And remember Our servants: Abraham, Isaac, and Jacob—the men of strength and insight','बेशक वह हमारी बारगाह में बड़े झुकने वाले थे और (ऐ रसूल) हमारे बन्दों में इब्राहीम और इसहाक़ और बेशक वह (हमारी बारगाह में) बड़े झुकने वाले थे और (ऐ रसूल) हमारे बन्दों में इबराहीम और इसहाक़ और याकूब को याद करो जो कुवत और बसीरत वाले थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,46,'Saad','إِنَّآ أَخۡلَصۡنَٰهُم بِخَالِصَةࣲ ذِكۡرَى ٱلدَّارِ','ہم نے ان کو ایک (صفت) خاص (آخرت کے) گھر کی یاد سے ممتاز کیا تھا','We truly chose them for the honour of proclaiming the Hereafter','हमने उन लोगों को एक ख़ास सिफत आख़ेरत की याद से मुमताज़ किया था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,47,'Saad','وَإِنَّهُمۡ عِندَنَا لَمِنَ ٱلۡمُصۡطَفَيۡنَ ٱلۡأَخۡيَارِ','اور ہمارے نزدیک منتخب اور نیک لوگوں میں سے تھے','And in Our sight they are truly among the chosen and the finest','और इसमें शक नहीं कि ये लोग हमारी बारगाह में बरगुज़ीदा और नेक लोगों में हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,48,'Saad','وَٱذۡكُرۡ إِسۡمَٰعِيلَ وَٱلۡيَسَعَ وَذَا ٱلۡكِفۡلِۖ وَكُلࣱّ مِّنَ ٱلۡأَخۡيَارِ','اور اسمٰعیل اور الیسع اور ذوالکفل کو یاد کرو۔ وہ سب نیک لوگوں میں سے تھے','Also remember Ishmael, Elisha, and Ⱬul-Kifl. All are among the best','और (ऐ रसूल) इस्माईल और अलयसा और जुलकिफ़ल को (भी) याद करो और (ये) सब नेक बन्दों में हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,49,'Saad','هَٰذَا ذِكۡرࣱۚ وَإِنَّ لِلۡمُتَّقِينَ لَحُسۡنَ مَـَٔابࣲ‏','یہ نصیحت ہے اور پرہیزگاروں کے لئے تو عمدہ مقام ہے','This is ˹all˺ a reminder. And the righteous will certainly have an honourable destination','ये एक नसीहत है और इसमें शक नहीं कि परहेज़गारों के लिए (आख़ेरत में) यक़ीनी अच्छी आरामगाह है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,50,'Saad','جَنَّٰتِ عَدۡنࣲ مُّفَتَّحَةࣰ لَّهُمُ ٱلۡأَبۡوَٰبُ','ہمیشہ رہنے کے باغ جن کے دروازے ان کے لئے کھلے ہوں گے','the Gardens of Eternity, whose gates will be open for them','(यानि) हमेशा रहने के (बेहिश्त के) सदाबहार बाग़ात जिनके दरवाज़े उनके लिए (बराबर) खुले होगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,51,'Saad','مُتَّكِـِٔينَ فِيهَا يَدۡعُونَ فِيهَا بِفَٰكِهَةࣲ كَثِيرَةࣲ وَشَرَابࣲ‏','ان میں تکیٴے لگائے بیٹھے ہوں گے اور (کھانے پینے کے لئے) بہت سے میوے اور شراب منگواتے رہیں گے','There they will recline, calling for abundant fruit and drink','और ये लोग वहाँ तकिये लगाए हुए (चैन से बैठे) होगें वहाँ (खुद्दामे बेहिश्त से) कसरत से मेवे और शराब मँगवाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,52,'Saad','۞وَعِندَهُمۡ قَٰصِرَٰتُ ٱلطَّرۡفِ أَتۡرَابٌ','اور ان کے پاس نیچی نگاہ رکھنے والی (اور) ہم عمر (عورتیں) ہوں گی','And with them will be maidens of modest gaze and equal age','और उनके पहलू में नीची नज़रों वाली (शरमीली) कमसिन बीवियाँ होगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,53,'Saad','هَٰذَا مَا تُوعَدُونَ لِيَوۡمِ ٱلۡحِسَابِ','یہ وہ چیزیں ہیں جن کا حساب کے دن کے لئے تم سے وعدہ کیا جاتا تھا','This is what you are promised for the Day of Reckoning','(मोमिनों) ये वह चीज़ हैं जिनका हिसाब के दिन (क़यामत) के लिए तुमसे वायदा किया जाता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,54,'Saad','إِنَّ هَٰذَا لَرِزۡقُنَا مَا لَهُۥ مِن نَّفَادٍ','یہ ہمارا رزق ہے جو کبھی ختم نہیں ہوگا','This is indeed Our provision that will never end','बेशक ये हमारी (दी हुई) रोज़ी है जो कभी तमाम न होगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,55,'Saad','هَٰذَاۚ وَإِنَّ لِلطَّٰغِينَ لَشَرَّ مَـَٔابࣲ‏','یہ (نعمتیں تو فرمانبرداروں کے لئے ہیں) اور سرکشوں کے لئے برا ٹھکانا ہے','That is that. And the transgressors will certainly have the worst destination','ये परहेज़गारों का (अन्जाम) है और सरकशों का तो यक़ीनी बुरा ठिकाना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,56,'Saad','جَهَنَّمَ يَصۡلَوۡنَهَا فَبِئۡسَ ٱلۡمِهَادُ','(یعنی) دوزخ۔ جس میں وہ داخل ہوں گے اور وہ بری آرام گاہ ہے','Hell, where they will burn. What an evil place to rest','जहन्नुम जिसमें उनको जाना पड़ेगा तो वह क्या बुरा ठिकाना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,57,'Saad','هَٰذَا فَلۡيَذُوقُوهُ حَمِيمࣱ وَغَسَّاقࣱ‏','یہ کھولتا ہوا گرم پانی اور پیپ (ہے) اب اس کے مزے چکھیں','Let them then taste this: boiling water and ˹oozing˺ pus','ये खौलता हुआ पानी और पीप और इस तरह अनवा अक़साम की दूसरी चीज़े हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,58,'Saad','وَءَاخَرُ مِن شَكۡلِهِۦٓ أَزۡوَٰجٌ','اور اسی طرح کے اور بہت سے (عذاب ہوں گے)','and other torments of the same sort','तो ये लोग उन्हीं पड़े चखा करें (कुछ लोगों के बारे में) बड़ों से कहा जाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,59,'Saad','هَٰذَا فَوۡجࣱ مُّقۡتَحِمࣱ مَّعَكُمۡ لَا مَرۡحَبَۢا بِهِمۡۚ إِنَّهُمۡ صَالُواْ ٱلنَّارِ','یہ ایک فوج ہے جو تمہارے ساتھ داخل ہوگی۔ ان کو خوشی نہ ہو یہ دوزخ میں جانے والے ہیں','˹The misleaders will say to one another,˺ “Here is a crowd ˹of followers˺ being thrown in with us. They are not welcome, ˹for˺ they ˹too˺ will burn in the Fire.”','ये (तुम्हारी चेलों की) फौज भी तुम्हारे साथ ही ढूँसी जाएगी उनका भला न हो ये सब भी दोज़ख़ को जाने वाले हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,60,'Saad','قَالُواْ بَلۡ أَنتُمۡ لَا مَرۡحَبَۢا بِكُمۡۖ أَنتُمۡ قَدَّمۡتُمُوهُ لَنَاۖ فَبِئۡسَ ٱلۡقَرَارُ','کہیں گے بلکہ تم ہی کو خوشی نہ ہو۔ تم ہی تو یہ (بلا) ہمارے سامنے لائے سو (یہ) برا ٹھکانا ہے','The followers will respond, “No! You are not welcome! You brought this upon us. What an evil place for settlement!”','तो चेले कहेंगें (हम क्यों) बल्कि तुम (जहन्नुमी हो) तुम्हारा ही भला न हो तो तुम ही लोगों ने तो इस (बला) से हमारा सामना करा दिया तो जहन्नुम भी क्या बुरी जगह है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,61,'Saad','قَالُواْ رَبَّنَا مَن قَدَّمَ لَنَا هَٰذَا فَزِدۡهُ عَذَابࣰ ا ضِعۡفࣰ ا فِي ٱلنَّارِ','وہ کہیں گے اے پروردگار جو اس کو ہمارے سامنے لایا ہے اس کو دوزخ میں دونا عذاب دے','Adding, “Our Lord! Whoever brought this upon us, double their punishment in the Fire.”','(फिर वह) अर्ज़ करेगें परवरदिगार जिस शख्स ने हमारा इस (बला) से सामना करा दिया तो तू उस पर हमसे बढ़कर जहन्नुम में दो गुना अज़ाब कर');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,62,'Saad','وَقَالُواْ مَا لَنَا لَا نَرَىٰ رِجَالࣰ ا كُنَّا نَعُدُّهُم مِّنَ ٱلۡأَشۡرَارِ','اور کہیں گے کیا سبب ہے کہ (یہاں) ہم ان شخصوں کو نہیں دیکھتے جن کو بروں میں شمار کرتے تھے','The tyrants will ask ˹one another˺, “But why do we not see those we considered to be lowly','और (फिर) खुद भी कहेगें हमें क्या हो गया है कि हम जिन लोगों को (दुनिया में) शरीर शुमार करते थे हम उनको यहाँ (दोज़ख़) में नहीं देखते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,63,'Saad','أَتَّخَذۡنَٰهُمۡ سِخۡرِيًّا أَمۡ زَاغَتۡ عَنۡهُمُ ٱلۡأَبۡصَٰرُ','کیا ہم نے ان سے ٹھٹھا کیا ہے یا (ہماری) آنکھیں ان (کی طرف) سے پھر گئی ہیں؟','Were we wrong in mocking them ˹in the world˺? Or do our eyes ˹just˺ fail to see them ˹in the Fire˺?”','क्या हम उनसे (नाहक़) मसखरापन करते थे या उनकी तरफ से (हमारी) ऑंखे पलट गयी हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,64,'Saad','إِنَّ ذَٰلِكَ لَحَقࣱّ تَخَاصُمُ أَهۡلِ ٱلنَّارِ','بےشک یہ اہل دوزخ کا جھگڑنا برحق ہے','This dispute between the residents of the Fire will certainly come to pass','इसमें शक नहीं कि जहन्नुमियों का बाहम झगड़ना ये बिल्कुल यक़ीनी ठीक है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,65,'Saad','قُلۡ إِنَّمَآ أَنَا۠ مُنذِرࣱۖ وَمَا مِنۡ إِلَٰهٍ إِلَّا ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ','کہہ دو کہ میں تو صرف ہدایت کرنے والا ہوں۔ اور خدائے یکتا اور غالب کے سوا کوئی معبود نہیں','Say, ˹O Prophet,˺ “I am only a warner. And there is no god ˹worthy of worship˺ except Allah—the One, the Supreme','(ऐ रसूल) तुम कह दो कि मैं तो बस (अज़ाबे खुदा से) डराने वाला हूँ और यकता क़हार खुदा के सिवा कोई माबूद क़ाबिले परसतिश नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,66,'Saad','رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا ٱلۡعَزِيزُ ٱلۡغَفَّٰرُ','جو آسمانوں اور زمین اور جو مخلوق ان میں ہے سب کا مالک ہے غالب (اور) بخشنے والا','˹He is the˺ Lord of the heavens and the earth and everything in between—the Almighty, Most Forgiving.”','सारे आसमान और ज़मीन का और जो चीज़े उन दोनों के दरमियान हैं (सबका) परवरदिगार ग़ालिब बड़ा बख्शने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,67,'Saad','قُلۡ هُوَ نَبَؤٌاْ عَظِيمٌ','کہہ دو کہ یہ ایک بڑی (ہولناک چیز کی) خبر ہے','Say, “This ˹Quran˺ is momentous news','(ऐ रसूल) तुम कह दो कि ये (क़यामत) एक बहुत बड़ा वाक़िया है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,68,'Saad','أَنتُمۡ عَنۡهُ مُعۡرِضُونَ','جس کو تم دھیان میں نہیں لاتے','from which you ˹pagans˺ are turning away.”','जिससे तुम लोग (ख्वाहमाख्वाह) मुँह फेरते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,69,'Saad','مَا كَانَ لِيَ مِنۡ عِلۡمِۭ بِٱلۡمَلَإِ ٱلۡأَعۡلَىٰٓ إِذۡ يَخۡتَصِمُونَ','مجھ کو اوپر کی مجلس (والوں) کا جب وہ جھگڑتے تھے کچھ بھی علم نہ تھا','˹And say,˺ “I had no knowledge of the highest assembly ˹in heaven˺ when they differed ˹concerning Adam˺','आलम बाला के रहने वाले (फरिश्ते) जब वाहम बहस करते थे उसकी मुझे भी ख़बर न थी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,70,'Saad','إِن يُوحَىٰٓ إِلَيَّ إِلَّآ أَنَّمَآ أَنَا۠ نَذِيرࣱ مُّبِينٌ','میری طرف تو یہی وحی کی جاتی ہے کہ میں کھلم کھلا ہدایت کرنے والا ہوں','What is revealed to me is that I am only sent with a clear warning.”','मेरे पास तो बस वही की गयी है कि मैं (खुदा के अज़ाब से) साफ-साफ डराने वाला हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,71,'Saad','إِذۡ قَالَ رَبُّكَ لِلۡمَلَٰٓئِكَةِ إِنِّي خَٰلِقُۢ بَشَرࣰ ا مِّن طِينࣲ‏','جب تمہارے پروردگار نے فرشتوں سے کہا کہ میں مٹی سے انسان بنانے والا ہوں','˹Remember, O Prophet˺ when your Lord said to the angels, “I am going to create a human being from clay','(वह बहस ये थी कि) जब तुम्हारे परवरदिगार ने फरिश्तों से कहा कि मैं गीली मिट्टी से एक आदमी बनाने वाला हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,72,'Saad','فَإِذَا سَوَّيۡتُهُۥ وَنَفَخۡتُ فِيهِ مِن رُّوحِي فَقَعُواْ لَهُۥ سَٰجِدِينَ','جب اس کو درست کرلوں اور اس میں اپنی روح پھونک دوں تو اس کے آگے سجدے میں گر پڑنا','So when I have fashioned him and had a spirit of My Own ˹creation˺ breathed into him, fall down in prostration to him.”','तो जब मैं उसको दुरूस्त कर लूँ और इसमें अपनी (पैदा) की हुई रूह फूँक दो तो तुम सब के सब उसके सामने सजदे में गिर पड़ना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,73,'Saad','فَسَجَدَ ٱلۡمَلَٰٓئِكَةُ كُلُّهُمۡ أَجۡمَعُونَ','تو تمام فرشتوں نے سجدہ کیا','So the angels prostrated all together—','तो सब के सब कुल फरिश्तों ने सजदा किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,74,'Saad','إِلَّآ إِبۡلِيسَ ٱسۡتَكۡبَرَ وَكَانَ مِنَ ٱلۡكَٰفِرِينَ','مگر شیطان اکڑ بیٹھا اور کافروں میں ہوگیا','but not Iblîs, who acted arrogantly, becoming unfaithful','मगर (एक) इबलीस ने कि वह शेख़ी में आ गया और काफिरों में हो गया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,75,'Saad','قَالَ يَٰٓإِبۡلِيسُ مَا مَنَعَكَ أَن تَسۡجُدَ لِمَا خَلَقۡتُ بِيَدَيَّۖ أَسۡتَكۡبَرۡتَ أَمۡ كُنتَ مِنَ ٱلۡعَالِينَ','(خدا نے) فرمایا کہ اے ابلیس جس شخص کو میں نے اپنے ہاتھوں سے بنایا اس کے آگے سجدہ کرنے سے تجھے کس چیز نے منع کیا۔ کیا تو غرور میں آگیا یا اونچے درجے والوں میں تھا؟','Allah asked, “O Iblîs! What prevented you from prostrating to what I created with My Own Hands? Did you ˹just˺ become proud? Or have you always been arrogant?”','ख़ुदा ने (इबलीस से) फरमाया कि ऐ इबलीस जिस चीज़ को मैंने अपनी ख़ास कुदरत से पैदा किया (भला) उसको सजदा करने से तुझे किसी ने रोका क्या तूने तक़ब्बुर किया या वाकई तू बड़े दरजे वालें में है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,76,'Saad','قَالَ أَنَا۠ خَيۡرࣱ مِّنۡهُ خَلَقۡتَنِي مِن نَّارࣲ وَخَلَقۡتَهُۥ مِن طِينࣲ‏','بولا کہ میں اس سے بہتر ہوں (کہ) تو نے مجھ کو کو آگ سے پیدا کیا اور اِسے مٹی سے بنایا','He replied, “I am better than he is: You created me from fire and him from clay.”','इबलीस बोल उठा कि मैं उससे बेहतर हूँ तूने मुझे आग से पैदा किया और इसको तूने गीली मिट्टी से पैदा किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,77,'Saad','قَالَ فَٱخۡرُجۡ مِنۡهَا فَإِنَّكَ رَجِيمࣱ‏','فرمایا یہاں سے نکل جا تو مردود ہے','Allah commanded, “Then get out of Paradise, for you are truly cursed','(कहाँ आग कहाँ मिट्टी) खुदा ने फरमाया कि तू यहाँ से निकल (दूर हो) तू यक़ीनी मरदूद है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,78,'Saad','وَإِنَّ عَلَيۡكَ لَعۡنَتِيٓ إِلَىٰ يَوۡمِ ٱلدِّينِ','اور تجھ پر قیامت کے دن تک میری لعنت (پڑتی) رہے گی','And surely upon you is My condemnation until the Day of Judgment.”','और तुझ पर रोज़ जज़ा (क़यामत) तक मेरी फिटकार पड़ा करेगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,79,'Saad','قَالَ رَبِّ فَأَنظِرۡنِيٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ','کہنے لگا کہ میرے پروردگار مجھے اس روز تک کہ لوگ اٹھائے جائیں مہلت دے','Satan appealed, “My Lord! Then delay my end until the Day of their resurrection.”','शैतान ने अर्ज़ की परवरदिगार तू मुझे उस दिन तक की मोहलत अता कर जिसमें सब लोग (दोबारा) उठा खड़े किए जायेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,80,'Saad','قَالَ فَإِنَّكَ مِنَ ٱلۡمُنظَرِينَ','فرمایا کہ تجھ کو مہلت دی جاتی ہے','Allah said, “You will be delayed','फरमाया तुझे एक वक्त मुअय्यन के दिन तक की मोहलत दी गयी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,81,'Saad','إِلَىٰ يَوۡمِ ٱلۡوَقۡتِ ٱلۡمَعۡلُومِ','اس روز تک جس کا وقت مقرر ہے','until the appointed Day.”','वह बोला तेरी ही इज्ज़त व जलाल की क़सम');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,82,'Saad','قَالَ فَبِعِزَّتِكَ لَأُغۡوِيَنَّهُمۡ أَجۡمَعِينَ','کہنے لگا کہ مجھے تیری عزت کی قسم میں ان سب کو بہکاتا رہوں گا','Satan said, “By Your Glory! I will certainly mislead them all','उनमें से तेरे ख़ालिस बन्दों के सिवा सब के सब को ज़रूर गुमराह करूँगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,83,'Saad','إِلَّا عِبَادَكَ مِنۡهُمُ ٱلۡمُخۡلَصِينَ','سوا ان کے جو تیرے خالص بندے ہیں','except Your chosen servants among them.”','खुदा ने फरमाया तो (हम भी) हक़ बात (कहे देते हैं)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,84,'Saad','قَالَ فَٱلۡحَقُّ وَٱلۡحَقَّ أَقُولُ','فرمایا سچ (ہے) اور میں بھی سچ کہتا ہوں','Allah concluded, “The truth is—and I ˹only˺ say the truth—','और मैं तो हक़ ही कहा करता हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,85,'Saad','لَأَمۡلَأَنَّ جَهَنَّمَ مِنكَ وَمِمَّن تَبِعَكَ مِنۡهُمۡ أَجۡمَعِينَ','کہ میں تجھ سے اور جو ان میں سے تیری پیروی کریں گے سب سے جہنم کو بھر دوں گا','I will surely fill up Hell with you and whoever follows you from among them, all together.”','कि मैं तुझसे और जो लोग तेरी ताबेदारी करेंगे उन सब से जहन्नुम को ज़रूर भरूँगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,86,'Saad','قُلۡ مَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرࣲ وَمَآ أَنَا۠ مِنَ ٱلۡمُتَكَلِّفِينَ','اے پیغمبر کہہ دو کہ میں تم سے اس کا صلہ نہیں مانگتا اور نہ میں بناوٹ کرنے والوں میں ہوں','Say, ˹O Prophet,˺ “I do not ask you for any reward for this ˹Quran˺, nor do I pretend to be someone I am not','(ऐ रसूल) तुम कह दो कि मैं तो तुमसे न इस (तबलीग़े रिसालत) की मज़दूरी माँगता हूँ और न मैं (झूठ मूठ) बनावट करने वाला हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,87,'Saad','إِنۡ هُوَ إِلَّا ذِكۡرࣱ لِّلۡعَٰلَمِينَ','یہ قرآن تو اہل عالم کے لئے نصیحت ہے','It is only a reminder to the whole world','ये (क़ुरान) तो बस सारे जहाँन के लिए नसीहत है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (38,88,'Saad','وَلَتَعۡلَمُنَّ نَبَأَهُۥ بَعۡدَ حِينِۭ','اور تم کو اس کا حال ایک وقت کے بعد معلوم ہوجائے گا','And you will certainly know its truth before long.”','और कुछ दिनों बाद तुमको इसकी हक़ीकत मालूम हो जाएगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,1,'Az-Zumar','تَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ','اس کتاب کا اُتارا جانا خدائے غالب (اور) حکمت والے کی طرف سے ہے','The revelation of this Book is from Allah—the Almighty, All-Wise','(इस) किताब (क़ुरान) का नाज़िल करना उस खुदा की बारगाह से है जो (सब पर) ग़ालिब हिकमत वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,2,'Az-Zumar','إِنَّآ أَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ فَٱعۡبُدِ ٱللَّهَ مُخۡلِصࣰ ا لَّهُ ٱلدِّينَ','(اے پیغمبر) ہم نے یہ کتاب تمہاری طرف سچائی کے ساتھ نازل کی ہے تو خدا کی عبادت کرو (یعنی) اس کی عبادت کو (شرک سے) خالص کرکے','Indeed, We have sent down the Book to you ˹O Prophet˺ in truth, so worship Allah ˹alone˺, being sincerely devoted to Him','(ऐ रसूल) हमने किताब (कुरान) को बिल्कुल ठीक नाज़िल किया है तो तुम इबादत को उसी के लिए निरा खुरा करके खुदा की बन्दगी किया करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,3,'Az-Zumar','أَلَا لِلَّهِ ٱلدِّينُ ٱلۡخَالِصُۚ وَٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَ مَا نَعۡبُدُهُمۡ إِلَّا لِيُقَرِّبُونَآ إِلَى ٱللَّهِ زُلۡفَىٰٓ إِنَّ ٱللَّهَ يَحۡكُمُ بَيۡنَهُمۡ فِي مَا هُمۡ فِيهِ يَخۡتَلِفُونَۗ إِنَّ ٱللَّهَ لَا يَهۡدِي مَنۡ هُوَ كَٰذِبࣱ كَفَّارࣱ‏','دیکھو خالص عبادت خدا ہی کے لئے (زیبا ہے) اور جن لوگوں نے اس کے سوا اور دوست بنائے ہیں۔ (وہ کہتے ہیں کہ) ہم ان کو اس لئے پوجتے ہیں کہ ہم کو خدا کا مقرب بنادیں۔ تو جن باتوں میں یہ اختلاف کرتے ہیں خدا ان میں ان کا فیصلہ کردے گا۔ بےشک خدا اس شخص کو جو جھوٹا ناشکرا ہے ہدایت نہیں دیتا','Indeed, sincere devotion is due ˹only˺ to Allah. As for those who take other lords besides Him, ˹saying,˺ “We worship them only so they may bring us closer to Allah,” surely Allah will judge between all regarding what they differed about. Allah certainly does not guide whoever persists in lying and disbelief','आगाह रहो कि इबादत तो ख़ास खुदा ही के लिए है और जिन लोगों ने खुदा के सिवा (औरों को अपना) सरपरस्त बना रखा है और कहते हैं कि हम तो उनकी परसतिश सिर्फ़ इसलिए करते हैं कि ये लोग खुदा की बारगाह में हमारा तक़र्रब बढ़ा देगें इसमें शक नहीं कि जिस बात में ये लोग झगड़ते हैं (क़यामत के दिन) खुदा उनके दरमियान इसमें फैसला कर देगा बेशक खुदा झूठे नाशुक्रे को मंज़िले मक़सूद तक नहीं पहुँचाया करता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,4,'Az-Zumar','لَّوۡ أَرَادَ ٱللَّهُ أَن يَتَّخِذَ وَلَدࣰ ا لَّٱصۡطَفَىٰ مِمَّا يَخۡلُقُ مَا يَشَآءُۚ سُبۡحَٰنَهُۥۖ هُوَ ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ','اگر خدا کسی کو اپنا بیٹا بنانا چاہتا تو اپنی مخلوق میں سے جس کو چاہتا انتخاب کرلیتا۔ وہ پاک ہے وہی تو خدا یکتا (اور) غالب ہے','Had it been Allah’s Will to have offspring, He could have chosen whatever He willed of His creation. Glory be to Him! He is Allah—the One, the Supreme','अगर खुदा किसी को (अपना) बेटा बनाना चाहता तो अपने मख़लूक़ात में से जिसे चाहता मुन्तखिब कर लेता (मगर) वह तो उससे पाक व पाकीज़ा है वह तो यकता बड़ा ज़बरदस्त अल्लाह है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,5,'Az-Zumar','خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۖ يُكَوِّرُ ٱلَّيۡلَ عَلَى ٱلنَّهَارِ وَيُكَوِّرُ ٱلنَّهَارَ عَلَى ٱلَّيۡلِۖ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلࣱّ يَجۡرِي لِأَجَلࣲ مُّسَمًّىۗ أَلَا هُوَ ٱلۡعَزِيزُ ٱلۡغَفَّٰرُ','اسی نے آسمانوں اور زمین کو تدبیر کے ساتھ پیدا کیا ہے۔ (اور) وہی رات کو دن پر لپیٹتا ہے اور دن کو رات پر لپیٹتا ہے اور اسی نے سورج اور چاند کو بس میں کر رکھا ہے۔ سب ایک وقت مقرر تک چلتے رہیں گے۔ دیکھو وہی غالب (اور) بخشنے والا ہے','He created the heavens and the earth for a purpose. He wraps the night around the day, and wraps the day around the night. And He has subjected the sun and the moon, each orbiting for an appointed term. He is truly the Almighty, Most Forgiving','उसी ने सारे आसमान और ज़मीन को बजा (दुरूस्त) पैदा किया वही रात को दिन पर ऊपर तले लपेटता है और वही दिन को रात पर तह ब तह लपेटता है और उसी ने आफताब और महताब को अपने बस में कर लिया है कि ये सबके सब अपने (अपने) मुक़रर्र वक्त चलते रहेगें आगाह रहो कि वही ग़ालिब बड़ा बख्शने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,6,'Az-Zumar','خَلَقَكُم مِّن نَّفۡسࣲ وَٰحِدَةࣲ ثُمَّ جَعَلَ مِنۡهَا زَوۡجَهَا وَأَنزَلَ لَكُم مِّنَ ٱلۡأَنۡعَٰمِ ثَمَٰنِيَةَ أَزۡوَٰجࣲۚ يَخۡلُقُكُمۡ فِي بُطُونِ أُمَّهَٰتِكُمۡ خَلۡقࣰ ا مِّنۢ بَعۡدِ خَلۡقࣲ فِي ظُلُمَٰتࣲ ثَلَٰثࣲۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ لَهُ ٱلۡمُلۡكُۖ لَآ إِلَٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُصۡرَفُونَ','اسی نے تم کو ایک شخص سے پیدا کیا پھر اس سے اس کا جوڑا بنایا اور اسی نے تمہارے لئے چار پایوں میں سے آٹھ جوڑے بنائے۔ وہی تم کو تمہاری ماؤں کے پیٹ میں (پہلے) ایک طرح پھر دوسری طرح تین اندھیروں میں بناتا ہے۔ یہی خدا تمہارا پروردگار ہے اسی کی بادشاہی ہے۔ اس کے سوا کوئی معبود نہیں پھر تم کہاں پھرے جاتے ہو؟','He created you ˹all˺ from a single soul, then from it He made its mate. And He produced for you four pairs of cattle. He creates you in the wombs of your mothers ˹in stages˺, one development after another, in three layers of darkness. That is Allah—your Lord! All authority belongs to Him. There is no god ˹worthy of worship˺ except Him. How can you then be turned away','उसी ने तुम सबको एक ही शख्स से पैदा किया फिर उस (की बाक़ी मिट्टी) से उसकी बीबी (हौव्वा) को पैदा किया और उसी ने तुम्हारे लिए आठ क़िस्म के चारपाए पैदा किए वही तुमको तुम्हारी माँओं के पेट में एक क़िस्म की पैदाइश के बाद दूसरी क़िस्म (नुत्फे जमा हुआ खून लोथड़ा) की पैदाइश से तेहरे तेहरे अंधेरों (पेट) रहम और झिल्ली में पैदा करता है वही अल्लाह तुम्हारा परवरदिगार है उसी की बादशाही है उसके सिवा माबूद नहीं तो तुम लोग कहाँ फिरे जाते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,7,'Az-Zumar','إِن تَكۡفُرُواْ فَإِنَّ ٱللَّهَ غَنِيٌّ عَنكُمۡۖ وَلَا يَرۡضَىٰ لِعِبَادِهِ ٱلۡكُفۡرَۖ وَإِن تَشۡكُرُواْ يَرۡضَهُ لَكُمۡۗ وَلَا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرۡجِعُكُمۡ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ','اگر ناشکری کرو گے تو خدا تم سے بےپروا ہے۔ اور وہ اپنے بندوں کے لئے ناشکری پسند نہیں کرتا اور اگر شکر کرو گے تو وہ اس کو تمہارے لئے پسند کرے گا۔ اور کوئی اٹھانے والا دوسرے کا بوجھ نہیں اٹھائے گا۔ پھر تم اپنے پروردگار کی طرف لوٹنا ہے۔ پھر جو کچھ تم کرتے رہے وہ تم کو بتائے گا۔ وہ تو دلوں کی پوشیدہ باتوں تک سے آگاہ ہے','If you disbelieve, then ˹know that˺ Allah is truly not in need of you, nor does He approve of disbelief from His servants. But if you become grateful ˹through faith˺, He will appreciate that from you. No soul burdened with sin will bear the burden of another. Then to your Lord is your return, and He will inform you of what you used to do. He certainly knows best what is ˹hidden˺ in the heart','अगर तुमने उसकी नाशुक्री की तो (याद रखो कि) खुदा तुमसे बिल्कुल बेपरवाह है और अपने बन्दों से कुफ्र और नाशुक्री को पसन्द नहीं करता और अगर तुम शुक्र करोगे तो वह उसको तुम्हारे वास्ते पसन्द करता है और (क़यामत में) कोई किसी (के गुनाह) का बोझ (अपनी गर्दन पर) नहीं उठाएगा फिर तुमको अपने परवरदिगार की तरफ लौटना है तो (दुनिया में) जो कुछ (भला बुरा) करते थे वह तुम्हें बता देगा वह यक़ीनन दिलों के राज़ (तक) से खूब वाक़िफ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,8,'Az-Zumar','۞وَإِذَا مَسَّ ٱلۡإِنسَٰنَ ضُرࣱّ دَعَا رَبَّهُۥ مُنِيبًا إِلَيۡهِ ثُمَّ إِذَا خَوَّلَهُۥ نِعۡمَةࣰ مِّنۡهُ نَسِيَ مَا كَانَ يَدۡعُوٓاْ إِلَيۡهِ مِن قَبۡلُ وَجَعَلَ لِلَّهِ أَندَادࣰ ا لِّيُضِلَّ عَن سَبِيلِهِۦۚ قُلۡ تَمَتَّعۡ بِكُفۡرِكَ قَلِيلًا إِنَّكَ مِنۡ أَصۡحَٰبِ ٱلنَّارِ','اور جب انسان کو تکلیف پہنچتی ہے تو اپنے پروردگار کو پکارتا (اور) اس کی طرف دل سے رجوع کرتا ہے۔ پھر جب وہ اس کو اپنی طرف سے کوئی نعمت دیتا ہے تو جس کام کے لئے پہلے اس کو پکارتا ہے اسے بھول جاتا ہے اور خدا کا شریک بنانے لگتا ہے تاکہ (لوگوں کو) اس کے رستے سے گمراہ کرے۔ کہہ دو کہ (اے کافر نعمت) اپنی ناشکری سے تھوڑا سا فائدہ اٹھالے۔ پھر تُو تو دوزخیوں میں ہوگا','When one is touched with hardship, they cry out to their Lord, turning to Him ˹alone˺. But as soon as He showers them with blessings from Him, they ˹totally˺ forget the One they had cried to earlier, and set up equals to Allah to mislead ˹others˺ from His Way. Say, ˹O Prophet,˺ “Enjoy your disbelief for a little while! You will certainly be one of the inmates of the Fire.”','और आदमी (की हालत तो ये है कि) जब उसको कोई तकलीफ पहुँचती है तो उसी की तरफ रूजू करके अपने परवरदिगार से दुआ करता है (मगर) फिर जब खुदा अपनी तरफ से उसे नेअमत अता फ़रमा देता है तो जिस काम के लिए पहले उससे दुआ करता था उसे भुला देता है और बल्कि खुदा का शरीक बनाने लगता है ताकि (उस ज़रिए से और लोगों को भी) उसकी राह से गुमराह कर दे (ऐ रसूल ऐसे शख्स से) कह दो कि थोड़े दिनों और अपने कुफ्र (की हालत) में चैन कर लो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,9,'Az-Zumar','أَمَّنۡ هُوَ قَٰنِتٌ ءَانَآءَ ٱلَّيۡلِ سَاجِدࣰ ا وَقَآئِمࣰ ا يَحۡذَرُ ٱلۡأٓخِرَةَ وَيَرۡجُواْ رَحۡمَةَ رَبِّهِۦۗ قُلۡ هَلۡ يَسۡتَوِي ٱلَّذِينَ يَعۡلَمُونَ وَٱلَّذِينَ لَا يَعۡلَمُونَۗ إِنَّمَا يَتَذَكَّرُ أُوْلُواْ ٱلۡأَلۡبَٰبِ','(بھلا مشرک اچھا ہے) یا وہ جو رات کے وقتوں میں زمین پر پیشانی رکھ کر اور کھڑے ہو کر عبادت کرتا اور آخرت سے ڈرتا اور اپنے پروردگار کی رحمت کی امید رکھتا ہے۔ کہو بھلا جو لوگ علم رکھتے ہیں اور جو نہیں رکھتے دونوں برابر ہوسکتے ہیں؟ (اور) نصیحت تو وہی پکڑتے ہیں جو عقلمند ہیں','˹Are they better˺ or those who worship ˹their Lord˺ devoutly in the hours of the night, prostrating and standing, fearing the Hereafter and hoping for the mercy of their Lord? Say, ˹O Prophet,˺ “Are those who know equal to those who do not know?” None will be mindful ˹of this˺ except people of reason','(आख़िर) तू यक़ीनी जहन्नुमियों में होगा क्या जो शख्स रात के अवक़ात में सजदा करके और खड़े-खड़े (खुदा की) इबादत करता हो और आख़ेरत से डरता हो अपने परवरदिगार की रहमत का उम्मीदवार हो (नाशुक्रे) काफिर के बराबर हो सकता है (ऐ रसूल) तुम पूछो तो कि भला कहीं जानने वाले और न जाननेवाले लोग बराबर हो सकते हैं (मगर) नसीहत इबरतें तो बस अक्लमन्द ही लोग मानते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,10,'Az-Zumar','قُلۡ يَٰعِبَادِ ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ رَبَّكُمۡۚ لِلَّذِينَ أَحۡسَنُواْ فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةࣱۗ وَأَرۡضُ ٱللَّهِ وَٰسِعَةٌۗ إِنَّمَا يُوَفَّى ٱلصَّٰبِرُونَ أَجۡرَهُم بِغَيۡرِ حِسَابࣲ‏','کہہ دو کہ اے میرے بندو جو ایمان لائے ہو اپنے پروردگار سے ڈرو۔ جنہوں نے اس دنیا میں نیکی کی ان کے لئے بھلائی ہے۔ اور خدا کی زمین کشادہ ہے۔ جو صبر کرنے والے ہیں ان کو بےشمار ثواب ملے گا','Say ˹O Prophet, that Allah says˺, “O My servants who believe! Be mindful of your Lord. Those who do good in this world will have a good reward. And Allah’s earth is spacious. Only those who endure patiently will be given their reward without limit.”','(ऐ रसूल) तुम कह दो कि ऐ मेरे ईमानदार बन्दों अपने परवरदिगार (ही) से डरते रहो (क्योंकि) जिन लोगों ने इस दुनिया में नेकी की उन्हीं के लिए (आख़ेरत में) भलाई है और खुदा की ज़मीन तो कुशादा है (जहाँ इबादत न कर सको उसे छोड़ दो) सब्र करने वालों ही की तो उनका भरपूर बेहिसाब बदला दिया जाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,11,'Az-Zumar','قُلۡ إِنِّيٓ أُمِرۡتُ أَنۡ أَعۡبُدَ ٱللَّهَ مُخۡلِصࣰ ا لَّهُ ٱلدِّينَ','کہہ دو کہ مجھ سے ارشاد ہوا ہے کہ خدا کی عبادت کو خالص کرکے اس کی بندگی کروں','Say, “I am commanded to worship Allah, being sincerely devoted to Him ˹alone˺','(ऐ रसूल) तुम कह दो कि मुझे तो ये हुक्म दिया गया है कि मैं इबादत को उसके लिए ख़ास करके खुदा ही की बन्दगी करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,12,'Az-Zumar','وَأُمِرۡتُ لِأَنۡ أَكُونَ أَوَّلَ ٱلۡمُسۡلِمِينَ','اور یہ بھی ارشاد ہوا ہے کہ میں سب سے اول مسلمان بنوں','And I am commanded to be the first of those who submit ˹to His Will˺.”','और मुझे तो ये हुक्म दिया गया है कि मैं सबसे पहल मुसलमान हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,13,'Az-Zumar','قُلۡ إِنِّيٓ أَخَافُ إِنۡ عَصَيۡتُ رَبِّي عَذَابَ يَوۡمٍ عَظِيمࣲ‏','کہہ دو کہ اگر میں اپنے پروردگار کا حکم نہ مانوں تو مجھے بڑے دن کے عذاب سے ڈر لگتا ہے','Say, “I truly fear—if I were to disobey my Lord—the torment of a tremendous Day.”','(ऐ रसूल) तुम कह दो कि अगर मैं अपने परवरदिगार की नाफरमानी करूँ तो मैं एक बड़ी (सख्त) दिन (क़यामत) के अज़ाब से डरता हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,14,'Az-Zumar','قُلِ ٱللَّهَ أَعۡبُدُ مُخۡلِصࣰ ا لَّهُۥ دِينِي','کہہ دو کہ میں اپنے دین کو (شرک سے) خالص کرکے اس کی عبادت کرتا ہوں','Say, “It is ˹only˺ Allah that I worship, being sincere in my devotion to Him','(ऐ रसूल) तुम कह दो कि मैं अपनी इबादत को उसी के वास्ते ख़ालिस करके खुदा ही की बन्दगी करता हूँ (अब रहे तुम) तो उसके सिवा जिसको चाहो पूजो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,15,'Az-Zumar','فَٱعۡبُدُواْ مَا شِئۡتُم مِّن دُونِهِۦۗ قُلۡ إِنَّ ٱلۡخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ وَأَهۡلِيهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ أَلَا ذَٰلِكَ هُوَ ٱلۡخُسۡرَانُ ٱلۡمُبِينُ','تو تم اس کے سوا جس کی چاہو پرستش کرو۔ کہہ دو کہ نقصان اٹھانے والے وہی لوگ ہیں جنہوں نے قیامت کے دن اپنے آپ کو اور اپنے گھر والوں کو نقصان میں ڈالا۔ دیکھو یہی صریح نقصان ہے','Worship then whatever ˹gods˺ you want instead of Him.” Say, “The ˹true˺ losers are those who will lose themselves and their families on Judgment Day. That is indeed the clearest loss.”','(ऐ रसूल) तुम कह दो कि फिल हक़ीक़त घाटे में वही लोग हैं जिन्होंने अपना और अपने लड़के वालों का क़यामत के दिन घाटा किया आगाह रहो कि सरीही (खुल्लम खुल्ला) घाटा यही है कि उनके लिए उनके ऊपर से आग ही के ओढ़ने होगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,16,'Az-Zumar','لَهُم مِّن فَوۡقِهِمۡ ظُلَلࣱ مِّنَ ٱلنَّارِ وَمِن تَحۡتِهِمۡ ظُلَلࣱۚ ذَٰلِكَ يُخَوِّفُ ٱللَّهُ بِهِۦ عِبَادَهُۥۚ يَٰعِبَادِ فَٱتَّقُونِ','ان کے اوپر تو آگ کے سائبان ہوں گے اور نیچے (اس کے) فرش ہوں گے۔ یہ وہ (عذاب) ہے جس سے خدا اپنے بندوں کو ڈراتا ہے۔ تو اے میرے بندو مجھ سے ڈرتے رہو','They will have layers of fire above and below them. That is what Allah warns His servants with. So fear Me, O My servants','और उनके नीचे भी (आग ही के) बिछौने ये वह अज़ाब है जिससे खुदा अपने बन्दों को डराता है तो ऐ मेरे बन्दों मुझी से डरते रहो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,17,'Az-Zumar','وَٱلَّذِينَ ٱجۡتَنَبُواْ ٱلطَّٰغُوتَ أَن يَعۡبُدُوهَا وَأَنَابُوٓاْ إِلَى ٱللَّهِ لَهُمُ ٱلۡبُشۡرَىٰۚ فَبَشِّرۡ عِبَادِ','اور جنہوں نے اس سے اجتناب کیا کہ بتوں کو پوجیں اور خدا کی طرف رجوع کیا ان کے لئے بشارت ہے۔ تو میرے بندوں کو بشارت سنا دو','And those who shun the worship of false gods, turning to Allah ˹alone˺, will have good news. So give good news to My servants ˹O Prophet˺—','और जो लोग बुतों से उनके पूजने से बचे रहे और ख़ुदा ही की तरफ रूजु की उनके लिए (जन्नत की) ख़ुशख़बरी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,18,'Az-Zumar','ٱلَّذِينَ يَسۡتَمِعُونَ ٱلۡقَوۡلَ فَيَتَّبِعُونَ أَحۡسَنَهُۥٓۚ أُوْلَٰٓئِكَ ٱلَّذِينَ هَدَىٰهُمُ ٱللَّهُۖ وَأُوْلَٰٓئِكَ هُمۡ أُوْلُواْ ٱلۡأَلۡبَٰبِ','جو بات کو سنتے اور اچھی باتوں کی پیروی کرتے ہیں۔ یہی وہ لوگ ہیں جن کو خدا نے ہدایت دی اور یہی عقل والے ہیں','those who listen to what is said and follow the best of it. These are the ones ˹rightly˺ guided by Allah, and these are ˹truly˺ the people of reason','तो (ऐ रसूल) तुम मेरे (ख़ास) बन्दों को खुशख़बरी दे दो जो बात को जी लगाकर सुनते हैं और फिर उसमें से अच्छी बात पर अमल करते हैं यही वह लोग हैं जिनकी खुदा ने हिदायत की और यही लोग अक्लमन्द हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,19,'Az-Zumar','أَفَمَنۡ حَقَّ عَلَيۡهِ كَلِمَةُ ٱلۡعَذَابِ أَفَأَنتَ تُنقِذُ مَن فِي ٱلنَّارِ','بھلا جس شخص پر عذاب کا حکم صادر ہوچکا۔ تو کیا تم (ایسے) دوزخی کو مخلصی دے سکو گے؟','What about those against whom the decree of torment has been justified? Is it you ˹O Prophet˺ who will then save those bound for the Fire','तो (ऐ रसूल) भला जिस शख्स पर अज़ाब का वायदा पूरा हो चुका हो तो क्या तुम उस शख्स की ख़लासी दे सकते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,20,'Az-Zumar','لَٰكِنِ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ لَهُمۡ غُرَفࣱ مِّن فَوۡقِهَا غُرَفࣱ مَّبۡنِيَّةࣱ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ وَعۡدَ ٱللَّهِ لَا يُخۡلِفُ ٱللَّهُ ٱلۡمِيعَادَ','لیکن جو لوگ اپنے پروردگار سے ڈرتے ہیں ان کے لئے اونچے اونچے محل ہیں جن کے اوپر بالا خانے بنے ہوئے ہیں۔ (اور) ان کے نیچے نہریں بہہ رہی ہیں۔ (یہ) خدا کا وعدہ ہے۔ خدا وعدے کے خلاف نہیں کرتا','But those mindful of their Lord will have ˹elevated˺ mansions, built one above the other, under which rivers flow. ˹That is˺ the promise of Allah. ˹And˺ Allah never fails in ˹His˺ promise','जो आग में (पड़ा) हो मगर जो लोग अपने परवरदिगार से डरते रहे उनके ऊँचे-ऊँचे महल हैं (और) बाला ख़ानों पर बालाख़ाने बने हुए हैं जिनके नीचे नहरें जारी हैं ये खुदा का वायदा है (और) वायदा ख़िलाफी नहीं किया करता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,21,'Az-Zumar','أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءࣰ فَسَلَكَهُۥ يَنَٰبِيعَ فِي ٱلۡأَرۡضِ ثُمَّ يُخۡرِجُ بِهِۦ زَرۡعࣰ ا مُّخۡتَلِفًا أَلۡوَٰنُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصۡفَرࣰّ ا ثُمَّ يَجۡعَلُهُۥ حُطَٰمًاۚ إِنَّ فِي ذَٰلِكَ لَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ','کیا تم نے نہیں دیکھا کہ خدا آسمان سے پانی نازل کرتا پھر اس کو زمین میں چشمے بنا کر جاری کرتا پھر اس سے کھیتی اُگاتا ہے جس کے طرح طرح کے رنگ ہوتے ہیں۔ پھر وہ خشک ہوجاتی ہے تو تم اس کو دیکھتے ہو (کہ) زرد (ہوگئی ہے) پھر اسے چورا چورا کر دیتا ہے۔ بےشک اس میں عقل والوں کے لئے نصیحت ہے','Do you not see that Allah sends down rain from the sky—channelling it through streams in the earth—then produces with it crops of various colours, then they dry up and you see them wither, and then He reduces them to chaff? Surely in this is a reminder for people of reason','क्या तुमने इस पर ग़ौर नहीं किया कि खुदा ही ने आसमान से पानी बरसाया फिर उसको ज़मीन में चश्में बनाकर जारी किया फिर उसके ज़रिए से रंग बिरंग (के गल्ले) की खेती उगाता है फिर (पकने के बाद) सूख जाती है तो तुम को वह ज़र्द दिखायी देती है फिर खुदा उसे चूर-चूर भूसा कर देता है बेशक इसमें अक्लमन्दों के लिए (बड़ी) इबरत व नसीहत है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,22,'Az-Zumar','أَفَمَن شَرَحَ ٱللَّهُ صَدۡرَهُۥ لِلۡإِسۡلَٰمِ فَهُوَ عَلَىٰ نُورࣲ مِّن رَّبِّهِۦۚ فَوَيۡلࣱ لِّلۡقَٰسِيَةِ قُلُوبُهُم مِّن ذِكۡرِ ٱللَّهِۚ أُوْلَٰٓئِكَ فِي ضَلَٰلࣲ مُّبِينٍ','بھلا جس شخص کا سینہ خدا نے اسلام کے لئے کھول دیا ہو اور وہ اپنے پروردگار کی طرف سے روشنی پر ہو (تو کیا وہ سخت دل کافر کی طرح ہوسکتا ہے) پس ان پر افسوس ہے جن کے دل خدا کی یاد سے سخت ہو رہے ہیں۔ اور یہی لوگ صریح گمراہی میں ہیں','Can ˹the misguided be like˺ those whose hearts Allah has opened to Islam, so they are enlightened by their Lord? So woe to those whose hearts are hardened at the remembrance of Allah! It is they who are clearly astray','तो क्या वह शख्स जिस के सीने को खुदा ने (क़ुबूल) इस्लाम के लिए कुशादा कर दिया है तो वह अपने परवरदिगार (की हिदायत) की रौशनी पर (चलता) है मगर गुमराहों के बराबर हो सकता है अफसोस तो उन लोगों पर है जिनके दिल खुदा की याद से (ग़ाफ़िल होकर) सख्त हो गए हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,23,'Az-Zumar','ٱللَّهُ نَزَّلَ أَحۡسَنَ ٱلۡحَدِيثِ كِتَٰبࣰ ا مُّتَشَٰبِهࣰ ا مَّثَانِيَ تَقۡشَعِرُّ مِنۡهُ جُلُودُ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُمۡ ثُمَّ تَلِينُ جُلُودُهُمۡ وَقُلُوبُهُمۡ إِلَىٰ ذِكۡرِ ٱللَّهِۚ ذَٰلِكَ هُدَى ٱللَّهِ يَهۡدِي بِهِۦ مَن يَشَآءُۚ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٍ','خدا نے نہایت اچھی باتیں نازل فرمائی ہیں (یعنی) کتاب (جس کی آیتیں باہم) ملتی جلتی (ہیں) اور دہرائی جاتی (ہیں) جو لوگ اپنے پروردگار سے ڈرتے ہیں ان کے بدن کے (اس سے) رونگٹے کھڑے ہوجاتے ہیں۔ پھر ان کے بدن اور دل نرم (ہو کر) خدا کی یاد کی طرف (متوجہ) ہوجاتے ہیں۔ یہی خدا کی ہدایت ہے وہ اس سے جس کو چاہتا ہے ہدایت دیتا ہے۔ اور جس کو خدا گمراہ کرے اس کو کوئی ہدایت دینے والا نہیں','˹It is˺ Allah ˹Who˺ has sent down the best message—a Book of perfect consistency and repeated lessons—which causes the skin ˹and hearts˺ of those who fear their Lord to tremble, then their skin and hearts soften at the mention of ˹the mercy of˺ Allah. That is the guidance of Allah, through which He guides whoever He wills. But whoever Allah leaves to stray will be left with no guide','ये लोग सरीही गुमराही में (पड़े) हैं ख़ुदा ने बहुत ही अच्छा कलाम (यावी ये) किताब नाज़िल फरमाई (जिसकी आयतें) एक दूसरे से मिलती जुलती हैं और (एक बात कई-कई बार) दोहराई गयी है उसके सुनने से उन लोगों के रोंगटे खड़े हो जाते हैं जो अपने परवरदिगार से डरते हैं फिर उनके जिस्म नरम हो जाते हैं और उनके दिल खुदा की याद की तरफ बा इतमेनान मुतावज्जे हो जाते हैं ये खुदा की हिदायत है इसी से जिसकी चाहता है हिदायत करता है और खुदा जिसको गुमराही में छोड़ दे तो उसको कोई राह पर लाने वाला नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,24,'Az-Zumar','أَفَمَن يَتَّقِي بِوَجۡهِهِۦ سُوٓءَ ٱلۡعَذَابِ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَقِيلَ لِلظَّٰلِمِينَ ذُوقُواْ مَا كُنتُمۡ تَكۡسِبُونَ','بھلا جو شخص قیامت کے دن اپنے منہ سے برے عذاب کو روکتا ہو (کیا وہ ویسا ہوسکتا ہے جو چین میں ہو) اور ظالموں سے کہا جائے گا کہ جو کچھ تم کرتے رہے تھے اس کے مزے چکھو','Are those who will only have their ˹bare˺ faces to shield themselves from the awful torment on Judgment Day ˹better than those in Paradise˺? It will ˹then˺ be said to the wrongdoers: “Reap what you sowed!”','तो क्या जो शख्स क़यामत के दिन अपने मुँह को बड़े अज़ाब की सिपर बनाएगा (नाज़ी के बराबर हो सकता है) और ज़ालिमों से कहा जाएगा कि तुम (दुनिया में) जैसा कुछ करते थे अब उसके मज़े चखो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,25,'Az-Zumar','كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَأَتَىٰهُمُ ٱلۡعَذَابُ مِنۡ حَيۡثُ لَا يَشۡعُرُونَ','جو لوگ ان سے پہلے تھے انہوں نے بھی تکذیب کی تھی تو ان پر عذاب ایسی جگہ سے آگیا کہ ان کو خبر ہی نہ تھی','Those before them ˹also˺ rejected ˹the truth˺, then the torment came upon them from where they least expected','जो लोग उनसे पहले गुज़र गए उन्होंने भी (पैग़म्बरों को) झुठलाया तो उन पर अज़ाब इस तरह आ पहुँचा कि उन्हें ख़बर भी न हुई');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,26,'Az-Zumar','فَأَذَاقَهُمُ ٱللَّهُ ٱلۡخِزۡيَ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ','پھر ان کو خدا نے دنیا کی زندگی میں رسوائی کا مزہ چکھا دیا۔ اور آخرت کا عذاب تو بہت بڑا ہے۔ کاش یہ سمجھ رکھتے','So Allah made them taste humiliation in this worldly life, but far worse is the punishment of the Hereafter, if only they knew','तो खुदा ने उन्हें (इसी) दुनिया की ज़िन्दगी में रूसवाई की लज्ज़त चखा दी और आख़ेरत का अज़ाब तो यक़ीनी उससे कहीं बढ़कर है काश ये लोग ये बात जानते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,27,'Az-Zumar','وَلَقَدۡ ضَرَبۡنَا لِلنَّاسِ فِي هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلࣲ لَّعَلَّهُمۡ يَتَذَكَّرُونَ','اور ہم نے لوگوں کے (سمجھانے کے) لئے اس قرآن میں ہر طرح کی مثالیں بیان کی ہیں تاکہ وہ نصیحت پکڑیں','We have certainly set forth every ˹kind of˺ lesson for people in this Quran, so perhaps they will be mindful','और हमने तो इस क़ुरान में लोगों के (समझाने के) वास्ते हर तरह की मिसाल बयान कर दी है ताकि ये लोग नसीहत हासिल करें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,28,'Az-Zumar','قُرۡءَانًا عَرَبِيًّا غَيۡرَ ذِي عِوَجࣲ لَّعَلَّهُمۡ يَتَّقُونَ','(یہ) قرآن عربی (ہے) جس میں کوئی عیب (اور اختلاف) نہیں تاکہ وہ ڈر مانیں','˹It is˺ a Quran ˹revealed˺ in Arabic without any crookedness, so perhaps they will be conscious ˹of Allah˺','(हम ने तो साफ और सलीस) एक अरबी कुरान (नाज़िल किया) जिसमें ज़रा भी कजी (पेचीदगी) नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,29,'Az-Zumar','ضَرَبَ ٱللَّهُ مَثَلࣰ ا رَّجُلࣰ ا فِيهِ شُرَكَآءُ مُتَشَٰكِسُونَ وَرَجُلࣰ ا سَلَمࣰ ا لِّرَجُلٍ هَلۡ يَسۡتَوِيَانِ مَثَلًاۚ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ','خدا ایک مثال بیان کرتا ہے کہ ایک شخص ہے جس میں کئی (آدمی) شریک ہیں۔ (مختلف المزاج اور) بدخو اور ایک آدمی خاص ایک شخص کا (غلام) ہے۔ بھلا دونوں کی حالت برابر ہے۔ (نہیں) الحمدلله بلکہ یہ اکثر لوگ نہیں جانتے','Allah sets forth the parable of a slave owned by several quarrelsome masters, and a slave owned by only one master. Are they equal in condition? Praise be to Allah! In fact, most of them do not know','ताकि ये लोग (समझकर) खुदा से डरे ख़ुदा ने एक मिसाल बयान की है कि एक शख्स (ग़ुलाम) है जिसमें कई झगड़ालू साझी हैं और एक ज़ालिम है कि पूरा एक शख्स का है उन दोनों की हालत यकसाँ हो सकती हैं (हरगिज़ नहीं) अल्हमदोलिल्लाह मगर उनमें अक्सर इतना भी नहीं जानते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,30,'Az-Zumar','إِنَّكَ مَيِّتࣱ وَإِنَّهُم مَّيِّتُونَ','(اے پیغمبر) تم بھی مر جاؤ گے اور یہ بھی مر جائیں گے','You ˹O Prophet˺ will certainly die, and they will die too','(ऐ रसूल) बेशक तुम भी मरने वाले हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,31,'Az-Zumar','ثُمَّ إِنَّكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ عِندَ رَبِّكُمۡ تَخۡتَصِمُونَ','پھر تم سب قیامت کے دن اپنے پروردگار کے سامنے جھگڑو گے (اور جھگڑا فیصل کردیا جائے گا)','Then on the Day of Judgment you will ˹all settle your˺ dispute before your Lord','और ये लोग भी यक़ीनन मरने वाले हैं फिर तुम लोग क़यामत के दिन अपने परवरदिगार की बारगाह में बाहम झगड़ोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,32,'Az-Zumar','۞فَمَنۡ أَظۡلَمُ مِمَّن كَذَبَ عَلَى ٱللَّهِ وَكَذَّبَ بِٱلصِّدۡقِ إِذۡ جَآءَهُۥٓۚ أَلَيۡسَ فِي جَهَنَّمَ مَثۡوࣰ ى لِّلۡكَٰفِرِينَ','تو اس سے بڑھ کر ظالم کون جو خدا پر جھوٹ بولے اور سچی بات جب اس کے پاس پہنچ جائے تو اسے جھٹلائے۔ کیا جہنم میں کافروں کا ٹھکانا نہیں ہے؟','Who then does more wrong than those who lie about Allah and reject the truth after it has reached them? Is Hell not a ˹fitting˺ home for the disbelievers','तो इससे बढ़कर ज़ालिम कौन होगा जो ख़ुदा पर झूठ (तूफान) बाँधे और जब उसके पास सच्ची बात आए तो उसको झुठला दे क्या जहन्नुम में कााफिरों का ठिकाना नहीं है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,33,'Az-Zumar','وَٱلَّذِي جَآءَ بِٱلصِّدۡقِ وَصَدَّقَ بِهِۦٓ أُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ','اور جو شخص سچی بات لے کر آیا اور جس نے اس کی تصدیق کی وہی لوگ متقی ہیں','And the one who has brought the truth and those who embrace it—it is they who are the righteous','(ज़रूर है) और याद रखो कि जो शख्स (रसूल) सच्ची बात लेकर आया वह और जिसने उसकी तसदीक़ की यही लोग तो परहेज़गार हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,34,'Az-Zumar','لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمۡۚ ذَٰلِكَ جَزَآءُ ٱلۡمُحۡسِنِينَ','وہ جو چاہیں گے ان کے لئے ان کے پروردگار کے پاس (موجود) ہے۔ نیکوکاروں کا یہی بدلہ ہے','They will have whatever they desire with their Lord. That is the reward of the good-doers','ये लोग जो चाहेंगे उनके लिए परवर दिगार के पास (मौजूद) है, ये नेकी करने वालों की जज़ाए ख़ैर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,35,'Az-Zumar','لِيُكَفِّرَ ٱللَّهُ عَنۡهُمۡ أَسۡوَأَ ٱلَّذِي عَمِلُواْ وَيَجۡزِيَهُمۡ أَجۡرَهُم بِأَحۡسَنِ ٱلَّذِي كَانُواْ يَعۡمَلُونَ','تاکہ خدا ان سے برائیوں کو جو انہوں نے کیں دور کردے اور نیک کاموں کا جو وہ کرتے رہے ان کو بدلہ دے','As such, Allah will absolve them of ˹even˺ the worst of what they did and reward them according to the best of what they used to do','ताकि ख़ुदा उन लोगों की बुराइयों को जो उन्होने की हैं दूर कर दे और उनके अच्छे कामों के एवज़ जो वह कर चुके थे उसका अज्र (सवाब) अता फरमाए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,36,'Az-Zumar','أَلَيۡسَ ٱللَّهُ بِكَافٍ عَبۡدَهُۥۖ وَيُخَوِّفُونَكَ بِٱلَّذِينَ مِن دُونِهِۦۚ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادࣲ‏','کیا خدا اپنے بندوں کو کافی نہیں۔ اور یہ تم کو ان لوگوں سے جو اس کے سوا ہیں (یعنی غیر خدا سے) ڈراتے ہیں۔ اور جس کو خدا گمراہ کرے اسے کوئی ہدایت دینے والا نہیں','Is Allah not sufficient for His servant? Yet they threaten you with other ˹powerless˺ gods besides Him! Whoever Allah leaves to stray will be left with no guide','क्या ख़ुदा अपने बन्दों (की मदद) के लिए काफ़ी नहीं है (ज़रूर है) और (ऐ रसूल) तुमको लोग ख़ुदा के सिवा (दूसरे माबूदों) से डराते हैं और ख़ुदा जिसे गुमराही में छोड़ दे तो उसका कोई राह पर लाने वाला नहीं है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,37,'Az-Zumar','وَمَن يَهۡدِ ٱللَّهُ فَمَا لَهُۥ مِن مُّضِلٍّۗ أَلَيۡسَ ٱللَّهُ بِعَزِيزࣲ ذِي ٱنتِقَامࣲ‏','اور جس کو خدا ہدایت دے اس کو کوئی گمراہ کرنے والا نہیں۔ کیا خدا غالب (اور) بدلہ لینے والا نہیں ہے؟','And whoever Allah guides, none can lead astray. Is Allah not Almighty, capable of punishment','और जिस शख्स की हिदायत करे तो उसका कोई गुमराह करने वाला नहीं। क्या ख़दा ज़बरदस्त और बदला लेने वाला नहीं है (ज़रूर है)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,38,'Az-Zumar','وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ لَيَقُولُنَّ ٱللَّهُۚ قُلۡ أَفَرَءَيۡتُم مَّا تَدۡعُونَ مِن دُونِ ٱللَّهِ إِنۡ أَرَادَنِيَ ٱللَّهُ بِضُرٍّ هَلۡ هُنَّ كَٰشِفَٰتُ ضُرِّهِۦٓ أَوۡ أَرَادَنِي بِرَحۡمَةٍ هَلۡ هُنَّ مُمۡسِكَٰتُ رَحۡمَتِهِۦۚ قُلۡ حَسۡبِيَ ٱللَّهُۖ عَلَيۡهِ يَتَوَكَّلُ ٱلۡمُتَوَكِّلُونَ','اور اگر تم ان سے پوچھو کہ آسمانوں اور زمین کو کس نے پیدا کیا تو کہہ دیں کہ خدا نے۔ کہو کہ بھلا دیکھو تو جن کو تم خدا کے سوا پکارتے ہو۔ اگر خدا مجھ کو کوئی تکلیف پہنچانی چاہے تو کیا وہ اس تکلیف کو دور کرسکتے ہیں یا اگر مجھ پر مہربانی کرنا چاہے تو وہ اس کی مہربانی کو روک سکتے ہیں؟ کہہ دو کہ مجھے خدا ہی کافی ہے۔ بھروسہ رکھنے والے اسی پر بھروسہ رکھتے ہیں','If you ask them ˹O Prophet˺ who created the heavens and the earth, they will certainly say, “Allah!” Ask ˹them˺, “Consider then whatever ˹idols˺ you invoke besides Allah: if it was Allah’s Will to harm me, could they undo that harm? Or if He willed ˹some˺ mercy for me, could they withhold His mercy?” Say, “Allah is sufficient for me. In Him ˹alone˺ the faithful put their trust.”','और (ऐ रसूल) अगर तुम इनसे पूछो कि सारे आसमान व ज़मीन को किसने पैदा किया तो ये लोग यक़ीनन कहेंगे कि ख़ुदा ने, तुम कह दो कि तो क्या तुमने ग़ौर किया है कि ख़ुदा को छोड़ कर जिन लोगों की तुम इबादत करते हो अगर ख़ुदा मुझे कोई तक़लीफ पहुँचाना चाहे तो क्या वह लोग उसके नुक़सान को (मुझसे) रोक सकते हैं या अगर ख़ुदा मुझ पर मेहरबानी करना चाहे तो क्या वह लोग उसकी मेहरबानी रोक सकते हैं (ऐ रसूल) तुम कहो कि ख़ुदा मेरे लिए काफ़ी है उसी पर भरोसा करने वाले भरोसा करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,39,'Az-Zumar','قُلۡ يَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَٰمِلࣱۖ فَسَوۡفَ تَعۡلَمُونَ','کہہ دو کہ اے قوم تم اپنی جگہ عمل کئے جاؤ میں (اپنی جگہ) عمل کئے جاتا ہوں۔ عنقریب تم کو معلوم ہوجائے گا','Say, ˹O Prophet,˺ “O my people! Persist in your ways, for I ˹too˺ will persist in mine. You will soon come to know','(ऐ रसूल) तुम कह दो कि ऐ मेरी क़ौम तुम अपनी जगह (जो चाहो) अमल किए जाओ मै');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,40,'Az-Zumar','مَن يَأۡتِيهِ عَذَابࣱ يُخۡزِيهِ وَيَحِلُّ عَلَيۡهِ عَذَابࣱ مُّقِيمٌ','کہ کس پر عذاب آتا ہے جو اسے رسوا کرے گا۔ اور کس پر ہمیشہ کا عذاب نازل ہوتا ہے','who will be visited by a humiliating torment ˹in this life˺ and overwhelmed by an everlasting punishment ˹in the next˺.”','भी (अपनी जगह) कुछ कर रहा हूँ, फिर अनक़रीब ही तुम्हें मालूम हो जाएगा कि किस पर वह आफत आती है जो उसको (दुनिया में) रूसवा कर देगी और (आख़िर में) उस पर दायमी अज़ाब भी नाज़िल होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,41,'Az-Zumar','إِنَّآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ لِلنَّاسِ بِٱلۡحَقِّۖ فَمَنِ ٱهۡتَدَىٰ فَلِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيۡهَاۖ وَمَآ أَنتَ عَلَيۡهِم بِوَكِيلٍ','ہم نے تم پر کتاب لوگوں (کی ہدایت) کے لئے سچائی کے ساتھ نازل کی ہے۔ تو جو شخص ہدایت پاتا ہے تو اپنے (بھلے کے) لئے اور جو گمراہ ہوتا ہے گمراہی سے تو اپنا ہی نقصان کرتا ہے۔ اور (اے پیغمبر) تم ان کے ذمہ دار نہیں ہو','Surely We have revealed to you the Book ˹O Prophet˺ with the truth for humanity. So whoever chooses to be guided, it is for their own good. And whoever chooses to stray, it is only to their own loss. You are not a keeper over them','(ऐ रसूल) हमने तुम्हारे पास (ये) किताब (क़ुरान) सच्चाई के साथ लोगों (की हिदायत) के वास्ते नाज़िल की है, पस जो राह पर आया तो अपने ही (भले के) लिए और जो गुमराह हुआ तो उसकी गुमराही का वबाल भी उसी पर है और फिर तुम कुछ उनके ज़िम्मेदार तो हो नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,42,'Az-Zumar','ٱللَّهُ يَتَوَفَّى ٱلۡأَنفُسَ حِينَ مَوۡتِهَا وَٱلَّتِي لَمۡ تَمُتۡ فِي مَنَامِهَاۖ فَيُمۡسِكُ ٱلَّتِي قَضَىٰ عَلَيۡهَا ٱلۡمَوۡتَ وَيُرۡسِلُ ٱلۡأُخۡرَىٰٓ إِلَىٰٓ أَجَلࣲ مُّسَمًّىۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوۡمࣲ يَتَفَكَّرُونَ','خدا لوگوں کے مرنے کے وقت ان کی روحیں قبض کرلیتا ہے اور جو مرے نہیں (ان کی روحیں) سوتے میں (قبض کرلیتا ہے) پھر جن پر موت کا حکم کرچکتا ہے ان کو روک رکھتا ہے اور باقی روحوں کو ایک وقت مقرر تک کے لئے چھوڑ دیتا ہے۔ جو لوگ فکر کرتے ہیں ان کے لئے اس میں نشانیاں ہیں','˹It is˺ Allah ˹Who˺ calls back the souls ˹of people˺ upon their death as well as ˹the souls˺ of the living during their sleep. Then He keeps those for whom He has ordained death, and releases the others until ˹their˺ appointed time. Surely in this are signs for people who reflect','ख़ुदा ही लोगों के मरने के वक्त उनकी रूहें (अपनी तरफ़) खींच बुलाता है और जो लोग नहीं मरे (उनकी रूहें) उनकी नींद में (खींच ली जाती हैं) बस जिन के बारे में ख़ुदा मौत का हुक्म दे चुका है उनकी रूहों को रोक रखता है और बाक़ी (सोने वालों की रूहों) को फिर एक मुक़र्रर वक्त तक के वास्ते भेज देता है जो लोग (ग़ौर) और फिक्र करते हैं उनके लिए (क़ुदरते ख़ुदा की) यक़ीनी बहुत सी निशानियाँ हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,43,'Az-Zumar','أَمِ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ شُفَعَآءَۚ قُلۡ أَوَلَوۡ كَانُواْ لَا يَمۡلِكُونَ شَيۡـࣰٔ ا وَلَا يَعۡقِلُونَ','کیا انہوں نے خدا کے سوا اور سفارشی بنالئے ہیں۔ کہو کہ خواہ وہ کسی چیز کا بھی اختیار نہ رکھتے ہوں اور نہ (کچھ) سمجھتے ہی ہوں','Or have they taken others besides Allah as intercessors? Say, ˹O Prophet,˺ “˹Would they do so,˺ even though those ˹idols˺ have neither authority nor intelligence?”','क्या उन लोगों ने ख़ुदा के सिवा (दूसरे) सिफारिशी बना रखे है (ऐ रसूल) तुम कह दो कि अगरचे वह लोग न कुछ एख़तेयार रखते हों न कुछ समझते हों');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,44,'Az-Zumar','قُل لِّلَّهِ ٱلشَّفَٰعَةُ جَمِيعࣰ اۖ لَّهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ ثُمَّ إِلَيۡهِ تُرۡجَعُونَ','کہہ دو کہ سفارش تو سب خدا ہی کے اختیار میں ہے۔ اسی کے لئے آسمانوں اور زمین کی بادشاہت ہے۔ پھر تم اسی کی طرف لوٹ کر جاؤ گے','Say, “All intercession belongs to Allah ˹alone˺. To Him belongs the kingdom of the heavens and the earth. Then to Him you will ˹all˺ be returned.”','(तो भी सिफारिशी बनाओगे) तुम कह दो कि सारी सिफारिश तो ख़ुदा के लिए ख़ास है- सारे आसमान व ज़मीन की हुकूमत उसी के लिए ख़ास है, फिर तुम लोगों को उसकी तरफ लौट कर जाना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,45,'Az-Zumar','وَإِذَا ذُكِرَ ٱللَّهُ وَحۡدَهُ ٱشۡمَأَزَّتۡ قُلُوبُ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِۖ وَإِذَا ذُكِرَ ٱلَّذِينَ مِن دُونِهِۦٓ إِذَا هُمۡ يَسۡتَبۡشِرُونَ','اور جب تنہا خدا کا ذکر کیا جاتا ہے تو جو لوگ آخرت پر ایمان نہیں رکھتے ان کے دل منقبض ہوجاتے ہیں۔ اور جب اس کے سوا اوروں کا ذکر کیا جاتا ہے تو خوش ہوجاتے ہیں','Yet when Allah alone is mentioned, the hearts of those who disbelieve in the Hereafter are filled with disgust. But as soon as those ˹gods˺ other than Him are mentioned, they are filled with joy','और जब सिर्फ अल्लाह का ज़िक्र किया जाता है तो जो लोग आख़ेरत पर ईमान नहीं रखते उनके दिल मुतनफ़िफ़र हो जाते हैं और जब ख़ुदा के सिवा और (माबूदों) का ज़िक्र किया जाता है तो बस फौरन उनकी बाछें खिल जाती हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,46,'Az-Zumar','قُلِ ٱللَّهُمَّ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ عَٰلِمَ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ أَنتَ تَحۡكُمُ بَيۡنَ عِبَادِكَ فِي مَا كَانُواْ فِيهِ يَخۡتَلِفُونَ','کہو کہ اے خدا (اے) آسمانوں اور زمین کے پیدا کرنے والے (اور) پوشیدہ اور ظاہر کے جاننے والے تو ہی اپنے بندوں میں ان باتوں کا جن میں وہ اختلاف کرتے رہے ہیں فیصلہ کرے گا','Say, ˹O Prophet,˺ “O Allah—Originator of the heavens and the earth, Knower of the seen and unseen! You will judge between Your servants regarding their differences.”','(ऐ रसूल) तुम कह दो कि ऐ ख़ुदा (ऐ) सारे आसमान और ज़मीन पैदा करने वाले, ज़ाहिर व बातिन के जानने वाले हक़ बातों में तेरे बन्दे आपस में झगड़ रहे हैं तू ही उनके दरमियान फैसला कर देगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (39,47,'Az-Zumar','وَلَوۡ أَنَّ لِلَّذِينَ ظَلَمُواْ مَا فِي ٱلۡأَرۡضِ جَمِيعࣰ ا وَمِثۡلَهُۥ مَعَهُۥ لَٱفۡتَدَوۡاْ بِهِۦ مِن سُوٓءِ ٱلۡعَذَابِ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَبَدَا لَهُم مِّنَ ٱللَّهِ مَا لَمۡ يَكُونُواْ يَحۡتَسِبُونَ','اور اگر ظالموں کے پاس وہ سب (مال ومتاع) ہو جو زمین میں ہے اور اس کے ساتھ اسی قدر اور ہو تو قیامت کے روز برے عذاب (سے مخلصی پانے) کے بدلے میں دے دیں۔ اور ان پر خدا کی طرف سے وہ امر ظاہر ہوجائے گا جس کا ان کو خیال بھی نہ تھا','Even if the wrongdoers were to possess everything in the world twice over, they would certainly offer it to ransom themselves from the horrible punishment on Judgment Day, for they will see from Allah what they had never expected','और अगर नाफरमानों के पास रूए ज़मीन की सारी काएनात मिल जाएग बल्कि उनके साथ उतनी ही और भी हो तो क़यामत के दिन ये लोग यक़ीनन सख्त अज़ाब का फ़िदया दे निकलें (और अपना छुटकारा कराना चाहें) और (उस वक्त) उनके सामने ख़ुदा की तरफ से वह बात पेश आएगी जिसका उन्हें वहम व गुमान भी न था');
